{"command": "cd /workspace && python3 -c "
import subprocess,time,sys,os,fcntl
p=subprocess.Popen(['./executable','* | parse \"*\" as w | count by w'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
p.stdin.write(b'a\n'); p.stdin.flush()
time.sleep(0.5)
fcntl.fcntl(p.stdout,fcntl.F_SETFL,os.O_NONBLOCK)
try: print('after1:',repr(p.stdout.read()))
except Exception as e: print('err',e)
p.stdin.write(b'a\nb\n'); p.stdin.flush()
time.sleep(0.5)
try: print('after2:',repr(p.stdout.read()))
except Exception as e: print('err',e)
p.stdin.close()
p.wait()
print('final:',repr(p.stdout.read()))
""}

