/// Ordering used for group keys / sorting. Null < Bool < Num < Str < Arr < Map
pub fn cmp_value(a: &Value, b: &Value) -> Ordering {
    fn rank(v: &Value) -> u8 {
        match v {
            Value::Null => 0,
            Value::Bool(_) => 1,
            Value::Num(_) => 2,
            Value::Str(_) => 3,
            Value::Arr(_) => 4,
            Value::Map(_) => 5,
        }
    }
    let (ra, rb) = (rank(a), rank(b));
    if ra != rb {
        return ra.cmp(&rb);
    }
    match (a, b) {
        (Value::Null, Value::Null) => Ordering::Equal,
        (Value::Bool(x), Value::Bool(y)) => x.cmp(y),
        (Value::Num(x), Value::Num(y)) => x.partial_cmp(y).unwrap_or(Ordering::Equal),
        (Value::Str(x), Value::Str(y)) => x.cmp(y),
        (Value::Arr(x), Value::Arr(y)) => {
            for (i, j) in x.iter().zip(y.iter()) {
                let o = cmp_value(i, j);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.len().cmp(&y.len())
        }
        (Value::Map(x), Value::Map(y)) => {
            for (i, j) in x.iter().zip(y.iter()) {
                if i.0 != j.0 {
                    return i.0.cmp(j.0);
                }
                let o = cmp_value(i.1, j.1);
                if o != Ordering::Equal {
                    return o;
                }
            }
            x.len().cmp(&y.len())
        }
        _ => Ordering::Equal,
    }
}

/// A minimal JSON parser (mirrors serde_json behaviour for our needs)
pub mod serde_json_like {
    #[derive(Debug, Clone, PartialEq)]
    pub enum Json {
        Null,
        Bool(bool),
        Num(f64),
        Str(String),
        Arr(Vec<Json>),
        Obj(Vec<(String, Json)>),
    }

    pub fn parse(s: &str) -> Result<Json, ()> {
        let b: Vec<char> = s.chars().collect();
        let mut i = 0usize;
        let v = parse_value(&b, &mut i)?;
        skip_ws(&b, &mut i);
        if i != b.len() {
            return Err(());
        }
        Ok(v)
    }

    fn skip_ws(b: &[char], i: &mut usize) {
        while *i < b.len() && (b[*i] == ' ' || b[*i] == '\t' || b[*i] == '\n' || b[*i] == '\r') {
            *i += 1;
        }
    }

    fn parse_value(b: &[char], i: &mut usize) -> Result<Json, ()> {
        skip_ws(b, i);
        if *i >= b.len() {
            return Err(());
        }
        match b[*i] {
            '{' => {
                *i += 1;
                let mut out = Vec::new();
                skip_ws(b, i);
                if *i < b.len() && b[*i] == '}' {
                    *i += 1;
                    return Ok(Json::Obj(out));
                }
                loop {
                    skip_ws(b, i);
                    let k = parse_string(b, i)?;
                    skip_ws(b, i);
                    if *i >= b.len() || b[*i] != ':' {
                        return Err(());
                    }
                    *i += 1;
                    let v = parse_value(b, i)?;
                    out.push((k, v));
                    skip_ws(b, i);
                    if *i >= b.len() {
                        return Err(());
                    }
                    if b[*i] == ',' {
                        *i += 1;
                        continue;
                    }
                    if b[*i] == '}' {
                        *i += 1;
                        return Ok(Json::Obj(out));
                    }
                    return Err(());
                }
            }
            '[' => {
                *i += 1;
                let mut out = Vec::new();
                skip_ws(b, i);
                if *i < b.len() && b[*i] == ']' {
                    *i += 1;
                    return Ok(Json::Arr(out));
                }
                loop {
                    let v = parse_value(b, i)?;
                    out.push(v);
                    skip_ws(b, i);
                    if *i >= b.len() {
                        return Err(());
                    }
                    if b[*i] == ',' {
                        *i += 1;
                        continue;
                    }
                    if b[*i] == ']' {
                        *i += 1;
                        return Ok(Json::Arr(out));
                    }
                    return Err(());
                }
            }
            '"' => {
                let s = parse_string(b, i)?;
                Ok(Json::Str(s))
            }
            't' => {
                if b.len() >= *i + 4 && &b[*i..*i + 4] == &['t', 'r', 'u', 'e'] {
                    *i += 4;
                    Ok(Json::Bool(true))
                } else {
                    Err(())
                }
            }
            'f' => {
                if b.len() >= *i + 5 && &b[*i..*i + 5] == &['f', 'a', 'l', 's', 'e'] {
                    *i += 5;
                    Ok(Json::Bool(false))
                } else {
                    Err(())
                }
            }
            'n' => {
                if b.len() >= *i + 4 && &b[*i..*i + 4] == &['n', 'u', 'l', 'l'] {
                    *i += 4;
                    Ok(Json::Null)
                } else {
                    Err(())
                }
            }
            _ => parse_num(b, i),
        }
    }

    fn parse_string(b: &[char], i: &mut usize) -> Result<String, ()> {
        if *i >= b.len() || b[*i] != '"' {
            return Err(());
        }
        *i += 1;
        let mut out = String::new();
        while *i < b.len() {
            let c = b[*i];
            *i += 1;
            match c {
                '"' => return Ok(out),
                '\\' => {
                    if *i >= b.len() {
                        return Err(());
                    }
                    let e = b[*i];
                    *i += 1;
                    match e {
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'b' => out.push('\u{08}'),
                        'f' => out.push('\u{0c}'),
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'u' => {
                            if *i + 4 > b.len() {
                                return Err(());
                            }
                            let mut n: u32 = 0;
                            for _ in 0..4 {
                                let d = b[*i];
                                let dv = match d.to_digit(16) {
                                    Some(d) => d,
                                    None => return Err(()),
                                };
                                n = n * 16 + dv;
                                *i += 1;
                            }
                            if (0xD800..0xDC00).contains(&n) {
                                // surrogate pair
                                if *i + 6 <= b.len() && b[*i] == '\\' && b[*i + 1] == 'u' {
                                    let mut n2: u32 = 0;
                                    for k in 0..4 {
                                        let d = b[*i + 2 + k];
                                        let dv = match d.to_digit(16) {
                                            Some(d) => d,
                                            None => return Err(()),
                                        };
                                        n2 = n2 * 16 + dv;
                                    }
                                    *i += 6;
                                    let c = 0x10000 + ((n - 0xD800) << 10) + (n2 - 0xDC00);
                                    if let Some(ch) = char::from_u32(c) {
                                        out.push(ch);
                                    }
                                } else {
                                    out.push('\u{FFFD}');
                                }
                            } else if let Some(ch) = char::from_u32(n) {
                                out.push(ch);
                            } else {
                                out.push('\u{FFFD}');
                            }
                        }
                        _ => return Err(()),
                    }
                }
                c => out.push(c),
            }
        }
        Err(())
    }

    fn parse_num(b: &[char], i: &mut usize) -> Result<Json, ()> {
        let start = *i;
        if *i < b.len() && (b[*i] == '-' || b[*i] == '+') {
            *i += 1;
        }
        let mut seen_digit = false;
        while *i < b.len() && b[*i].is_ascii_digit() {
            seen_digit = true;
            *i += 1;
        }
        if *i < b.len() && b[*i] == '.' {
            *i += 1;
            while *i < b.len() && b[*i].is_ascii_digit() {
                seen_digit = true;
                *i += 1;
            }
        }
        if *i < b.len() && (b[*i] == 'e' || b[*i] == 'E') {
            *i += 1;
            if *i < b.len() && (b[*i] == '+' || b[*i] == '-') {
                *i += 1;
            }
            let mut ed = false;
            while *i < b.len() && b[*i].is_ascii_digit() {
                ed = true;
                *i += 1;
            }
            if !ed {
                return Err(());
            }
        }
        if !seen_digit {
            return Err(());
        }
        let s: String = b[start..*i].iter().collect();
        let n: f64 = s.parse().map_err(|_| ())?;
        Ok(Json::Num(n))
    }
}
