    Le,
    Gt,
    Ge,
    And,
    Or,
}

#[derive(Clone, Debug)]
pub enum Expr {
    Path(Path),
    Lit(Value),
    Bin(BinOp, Box<Expr>, Box<Expr>),
    Not(Box<Expr>),
    Func(String, Vec<Expr>),
}

impl Expr {
    pub fn src(&self) -> String {
        match self {
            Expr::Path(p) => p.src.clone(),
            Expr::Lit(v) => match v {
                Value::Str(s) => format!("\"{}\"", s),
                other => other.display(),
            },
            Expr::Bin(op, l, r) => {
                let o = match op {
                    BinOp::Add => "+",
                    BinOp::Sub => "-",
                    BinOp::Mul => "*",
                    BinOp::Div => "/",
                    BinOp::Eq => "==",
                    BinOp::Ne => "!=",
                    BinOp::Lt => "<",
                    BinOp::Le => "<=",
                    BinOp::Gt => ">",
                    BinOp::Ge => ">=",
                    BinOp::And => "and",
                    BinOp::Or => "or",
                };
                format!("{} {} {}", l.src(), o, r.src())
            }
            Expr::Not(e) => format!("!{}", e.src()),
            Expr::Func(name, args) => {
