    pub help: Vec<String>,
}

pub struct Diags {
    pub items: Vec<Diag>,
}

impl Diags {
    pub fn new() -> Self {
        Diags { items: Vec::new() }
    }
    pub fn push(&mut self, d: Diag) {
        self.items.push(d);
    }
    /// push `n` copies (the original tool reports some errors more than once)
