// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

pub struct P<'a> {
    s: &'a [u8],
    pub pos: usize,
    pub diags: Diags,
    /// inside a parenthesised region (affects unterminated string spans)
    paren_depth: usize,
}

pub type PResult<T> = Result<T, ()>;

fn is_ident_start(c: u8) -> bool {
    c.is_ascii_alphabetic() || c == b'_' || c >= 0x80
}
fn is_ident_char(c: u8) -> bool {
    c.is_ascii_alphanumeric() || c == b'_' || c == b'.' || c >= 0x80
}

impl<'a> P<'a> {
    pub fn new(s: &'a str) -> Self {
        P {
            s: s.as_bytes(),
            pos: 0,
            diags: Diags::new(),
            paren_depth: 0,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.s.get(self.pos).copied()
    }
    fn peek_at(&self, off: usize) -> Option<u8> {
        self.s.get(self.pos + off).copied()
    }
    fn rest(&self) -> &'a [u8] {
        &self.s[self.pos..]
    }
    fn rest_str(&self) -> String {
        String::from_utf_lossy(self.rest()).to_string()
    }
    fn eof(&self) -> bool {
        self.pos >= self.s.len()
    }
    fn starts_with(&self, t: &str) -> bool {
        self.s[self.pos..].starts_with(t.as_bytes())
    }
    fn skip_ws(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn err_here(&mut self, msg: &str, n: usize) -> PResult<()> {
        let len = 1.min(self.s.len() - self.pos.min(self.s.len())).max(1);
        self.diags.push_n(
            Diag {
                message: msg.to_string(),
                start: self.pos.min(self.s.len()),
                len,
                label: None,
                help: Vec::new(),
            },
            n,
        );
        Err(())
    }

    // ------------------------------------------------------------------
    // top level
    // ------------------------------------------------------------------
    pub fn parse_query(&mut self) -> PResult<Query> {
        let filters = self.parse_filters()?;
        let mut ops = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() {
                break;
            }
            if self.peek() == Some(b'|') {
                self.pos += 1;
                self.skip_ws();
                if self.eof() {
                    return self.err_here("expecting an expression", 1);
                }
                let op = self.parse_operator()?;
                ops.push(op);
            } else {
                return self.err_here("unhandled input", 4);
            }
        }
        Ok(Query { filters, ops })
    }

    // ------------------------------------------------------------------
    // filters
    // ------------------------------------------------------------------
    fn parse_filters(&mut self) -> PResult<Option<Filter>> {
        self.skip_ws();
        if self.eof() {
            return Ok(None);
        }
        if self.peek() == Some(b'|') {
            return Ok(None);
        }
        let f = self.parse_filter_or()?;
        Ok(Some(f))
    }

    fn parse_filter_or(&mut self) -> PResult<Filter> {
        let mut items = vec![self.parse_filter_and()?];
        loop {
            self.skip_ws();
            if self.starts_with_ci("or") && self.is_word_end(2) {
                self.pos += 2;
                self.skip_ws();
                items.push(self.parse_filter_and()?);
            } else {
                break;
            }
        }
        if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else {
            Ok(Filter::Or(items))
        }
    }

    fn parse_filter_and(&mut self) -> PResult<Filter> {
        let mut items = vec![self.parse_filter_item()?];
        loop {
            self.skip_ws();
            if self.starts_with_ci("and") && self.is_word_end(3) {
                self.pos += 3;
                self.skip_ws();
                items.push(self.parse_filter_item()?);
            } else if self.starts_with_ci("not") && self.is_word_end(3) {
                // not binds tighter: handled in item
                break;
            } else if self.eof() || self.peek() == Some(b'|') || self.peek() == Some(b')') {
                break;
            } else {
                // implicit AND
                items.push(self.parse_filter_item()?);
            }
        }
        if items.len() == 1 {
            Ok(items.pop().unwrap())
        } else {
            Ok(Filter::And(items))
        }
    }

    fn is_word_end(&self, off: usize) -> bool {
        match self.peek_at(off) {
            None => true,
            Some(c) => !(c.is_ascii_alphanumeric() || c == b'_'),
        }
    }

    fn starts_with_ci(&self, t: &str) -> bool {
        let b = self.rest();
        if b.len() < t.len() {
            return false;
        }
        b[..t.len()]
            .eq_ignore_ascii_case(t.as_bytes())
    }

    fn parse_filter_item(&mut self) -> PResult<Filter> {
        self.skip_ws();
        if self.eof() || self.peek() == Some(b'|') {
            return self.err_here("expecting an expression", 1);
        }
        if self.peek() == Some(b')') {
            return self.err_here("unhandled input", 4);
        }
        // NOT
        if self.starts_with_ci("not") && self.is_word_end(3) {
            let save = self.pos;
            self.pos += 3;
            self.skip_ws();
            if self.eof() || self.peek() == Some(b'|') {
                // "not" as a plain token
                self.pos = save;
                return self.parse_filter_atom();
            }
            let inner = self.parse_filter_item()?;
            return Ok(Filter::Not(Box::new(inner)));
        }
        self.parse_filter_atom()
    }

    fn parse_filter_atom(&mut self) -> PResult<Filter> {
        self.skip_ws();
        match self.peek() {
            None => self.err_here("expecting an expression", 1),
            Some(b'(') => {
                self.pos += 1;
                self.paren_depth += 1;
                let inner = self.parse_filter_or()?;
                self.skip_ws();
                if self.peek() == Some(b')') {
                    self.pos += 1;
                    self.paren_depth -= 1;
                    Ok(inner)
                } else {
                    let start = self.s.len() - self.rest().len();
                    let d = self.diags.items.len();
                    self.unterminated_paren(start);
                    let _ = d;
                    Err(())
                }
            }
            Some(q @ (b'"' | b'\'')) => {
                let start = self.pos;
                self.pos += 1;
                let mut s = String::new();
                let mut closed = false;
                while let Some(c) = self.peek() {
                    if c == q {
                        self.pos += 1;
                        closed = true;
                        break;
                    }
                    if c == b'\\' {
                        self.pos += 1;
                        if let Some(e) = self.peek() {
                            s.push(e as char);
                            self.pos += 1;
                        }
                        continue;
                    }
                    // take a full utf8 char
                    let len = utf8_len(&self.s[self.pos..]);
                    s.push_str(&String::from_utf_lossy(&self.s[self.pos..self.pos + len]));
                    self.pos += len;
                }
                if !closed {
                    let end = self.unterminated_string_end(start);
                    self.diags.push_n(
                        Diag {
                            message: if q == b'"' {
                                "unterminated double quoted string".to_string()
                            } else {
                                "unterminated single quoted string".to_string()
                            },
                            start,
                            len: end - start,
                            label: None,
                            help: vec![format!(
                                "Insert a {} quote ({}) to terminate this string",
                                if q == b'"' { "double" } else { "single" },
                                q as char
                            )],
                        },
                        4,
                    );
                    return Err(());
                }
                Ok(Filter::Match {
                    pat: s,
                    insensitive: false,
                })
            }
            Some(_) => {
                // bare token: up to whitespace or ) or | or (
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
                        break;
                    }
                    if c == b'(' || c == b')' {
                        break;
                    }
                    if c == b'|' {
                        break;
                    }
                    if c == b'"' || c == b'\'' {
                        break;
                    }
                    self.pos += 1;
                }
                if self.pos == start {
                    // unhandled input at this position
                    let c = self.peek().unwrap();
                    if c == b'|' {
                        return self.err_here("unhandled input", 4);
                    }
                    return self.err_here("unhandled input", 4);
                }
                let tok = String::from_utf_lossy(&self.s[start..self.pos]).to_string();
                let mut filters = vec![Filter::Match {
                    pat: tok,
                    insensitive: true,
                }];
                // additional whitespace separated tokens are implicitly AND'ed
                loop {
                    self.skip_ws();
                    match self.peek() {
                        None | Some(b'|') | Some(b')') => break,
                        Some(b'(') => break,
                        Some(q @ (b'"' | b'\'')) => {
                            let save = self.pos;
                            self.pos += 1;
                            let mut s = String::new();
                            let mut closed = false;
                            while let Some(c) = self.peek() {
                                if c == q {
                                    self.pos += 1;
                                    closed = true;
                                    break;
                                }
                                let len = utf8_len(&self.s[self.pos..]);
                                s.push_str(&String::from_utf_lossy(&self.s[self.pos..self.pos + len]));
                                self.pos += len;
                            }
                            if !closed {
                                self.pos = save;
                                break;
                            }
                            filters.push(Filter::Match {
                                pat: s,
                                insensitive: false,
                            });
                        }
                        Some(c) if is_ident_start(c) => {
                            let start = self.pos;
                            while let Some(c) = self.peek() {
                                if c == b' '
                                    || c == b'\t'
                                    || c == b'\r'
                                    || c == b'\n'
                                    || c == b'('
                                    || c == b')'
                                    || c == b'|'
                                    || c == b'"'
                                    || c == b'\''
                                {
                                    break;
                                }
                                self.pos += 1;
                            }
                            let tok = String::from_utf_lossy(&self.s[start..self.pos]).to_string();
                            filters.push(Filter::Match {
                                pat: tok,
                                insensitive: true,
                            });
                        }
                        _ => {
                            return self.err_here("unhandled input", 4);
                        }
                    }
                }
                if filters.len() == 1 {
                    Ok(filters.pop().unwrap())
                } else {
                    Ok(Filter::And(filters))
                }
            }
        }
    }

    fn unterminated_paren(&mut self, start: usize) {
        self.diags.push_n(
            Diag {
                message: "unterminated parenthesized filter".to_string(),
                start,
                len: self.s.len() - start,
                label: Some("unterminated parenthesized filter".to_string()),
                help: vec!["Insert a right parenthesis to terminate this filter".to_string()],
            },
            4,
        );
    }

    fn unterminated_string_end(&self, start: usize) -> usize {
        // an unterminated string runs until the end of the query or up to the
        // next closing parenthesis when we are inside one
        if self.paren_depth > 0 {
            let mut i = start;
            while i < self.s.len() {
                if self.s[i] == b')' {
                    return i;
                }
                i += 1;
            }
            self.s.len()
        } else {
            self.s.len()
        }
    }
}

fn utf8_len(b: &[u8]) -> usize {
    if b.is_empty() {
        return 0;
    }
    let c = b[0];
    if c < 0x80 {
        1
    } else if c >> 5 == 0b110 {
        2
    } else if c >> 4 == 0b1110 {
        3
    } else if c >> 3 == 0b11110 {
        4
    } else {
        1
    }
}
RSEOF
echo ok"}

