    // top level
    // ------------------------------------------------------------------
    pub fn parse_query(&mut self) -> PResult<Query> {
        let filters = self.parse_filters()?;
        let mut ops = Vec::new();
        loop {
            self.skip_ws();
            if self.eof() {
                break;
            }
            if self.peek() == Some(b'|') {
                self.pos += 1;
                self.skip_ws();
                if self.eof() {
                    return self.err_here("expecting an expression", 1);
                }
                let op = self.parse_operator()?;
                ops.push(op);
            } else {
                return self.err_here("unhandled input", 4);
            }
        }
        Ok(Query { filters, ops })
    }

    // ------------------------------------------------------------------
    // filters
    // ------------------------------------------------------------------
    fn parse_filters(&mut self) -> PResult<Option<Filter>> {
        self.skip_ws();
        if self.eof() {
            return Ok(None);
        }
        if self.peek() == Some(b'|') {
            return Ok(None);
        }
        let f = self.parse_filter_or()?;
        Ok(Some(f))
