        self.diags.push_n(
            Diag {
                message: "unterminated parenthesized filter".to_string(),
                start,
                len: self.s.len() - start,
                label: Some("unterminated parenthesized filter".to_string()),
                help: vec!["Insert a right parenthesis to terminate this filter".to_string()],
            },
            4,
        );
    }

    fn unterminated_string_end(&self, start: usize) -> usize {
        // an unterminated string runs until the end of the query or up to the
        // next closing parenthesis when we are inside one
