            let mut i = start;
            while i < self.s.len() {
                if self.s[i] == b')' {
                    return i;
                }
                i += 1;
            }
            self.s.len()
        } else {
            self.s.len()
        }
    }
}

fn utf8_len(b: &[u8]) -> usize {
    if b.is_empty() {
        return 0;
    }
    let c = b[0];
    if c < 0x80 {
        1
    } else if c >> 5 == 0b110 {
        2
    } else if c >> 4 == 0b1110 {
        3
    } else if c >> 3 == 0b11110 {
        4
    } else {
        1
    }
}
