                                "unterminated double quoted string".to_string()
                            } else {
                                "unterminated single quoted string".to_string()
                            },
                            start,
                            len: end - start,
                            label: None,
                            help: vec![format!(
                                "Insert a {} quote ({}) to terminate this string",
                                if q == b'"' { "double" } else { "single" },
                                q as char
                            )],
                        },
                        4,
                    );
                    return Err(());
                }
                Ok(Filter::Match {
                    pat: s,
                    insensitive: false,
                })
            }
            Some(_) => {
                // bare token: up to whitespace or ) or | or (
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
                        break;
                    }
                    if c == b'(' || c == b')' {
                        break;
                    }
                    if c == b'|' {
                        break;
                    }
                    if c == b'"' || c == b'\'' {
                        break;
                    }
                    self.pos += 1;
                }
                if self.pos == start {
                    // unhandled input at this position
                    let c = self.peek().unwrap();
                    if c == b'|' {
                        return self.err_here("unhandled input", 4);
                    }
                    return self.err_here("unhandled input", 4);
                }
                let tok = String::from_utf_lossy(&self.s[start..self.pos]).to_string();
                let mut filters = vec![Filter::Match {
                    pat: tok,
                    insensitive: true,
                }];
                // additional whitespace separated tokens are implicitly AND'ed
                loop {
                    self.skip_ws();
                    match self.peek() {
                        None | Some(b'|') | Some(b')') => break,
                        Some(b'(') => break,
                        Some(q @ (b'"' | b'\'')) => {
                            let save = self.pos;
                            self.pos += 1;
                            let mut s = String::new();
                            let mut closed = false;
                            while let Some(c) = self.peek() {
                                if c == q {
                                    self.pos += 1;
                                    closed = true;
                                    break;
                                }
                                let len = utf8_len(&self.s[self.pos..]);
                                s.push_str(&String::from_utf_lossy(&self.s[self.pos..self.pos + len]));
                                self.pos += len;
                            }
                            if !closed {
                                self.pos = save;
                                break;
                            }
                            filters.push(Filter::Match {
                                pat: s,
                                insensitive: false,
                            });
                        }
                        Some(c) if is_ident_start(c) => {
                            let start = self.pos;
                            while let Some(c) = self.peek() {
                                if c == b' '
                                    || c == b'\t'
                                    || c == b'\r'
                                    || c == b'\n'
                                    || c == b'('
                                    || c == b')'
                                    || c == b'|'
                                    || c == b'"'
                                    || c == b'\''
                                {
                                    break;
                                }
                                self.pos += 1;
                            }
                            let tok = String::from_utf_lossy(&self.s[start..self.pos]).to_string();
                            filters.push(Filter::Match {
                                pat: tok,
                                insensitive: true,
                            });
                        }
                        _ => {
                            return self.err_here("unhandled input", 4);
                        }
                    }
                }
                if filters.len() == 1 {
                    Ok(filters.pop().unwrap())
                } else {
                    Ok(Filter::And(filters))
                }
            }
        }
    }

    fn unterminated_paren(&mut self, start: usize) {
        self.diags.push_n(
            Diag {
                message: "unterminated parenthesized filter".to_string(),
                start,
                len: self.s.len() - start,
                label: Some("unterminated parenthesized filter".to_string()),
                help: vec!["Insert a right parenthesis to terminate this filter".to_string()],
            },
            4,
        );
    }

    fn unterminated_string_end(&self, start: usize) -> usize {
        // an unterminated string runs until the end of the query or up to the
        // next closing parenthesis when we are inside one
        if self.paren_depth > 0 {
            let mut i = start;
            while i < self.s.len() {
                if self.s[i] == b')' {
                    return i;
                }
                i += 1;
            }
            self.s.len()
        } else {
            self.s.len()
        }
    }
}

fn utf8_len(b: &[u8]) -> usize {
    if b.is_empty() {
        return 0;
    }
    let c = b[0];
    if c < 0x80 {
        1
    } else if c >> 5 == 0b110 {
        2
    } else if c >> 4 == 0b1110 {
        3
    } else if c >> 3 == 0b11110 {
        4
    } else {
        1
    }
}
