//! Operator + expression parsing.

use crate::query::*;
use crate::value::Value;

pub enum OpErr {
    /// parsing of the operator failed silently, other alternatives may match
    Graceful,
    /// a diagnostic was raised: stop parsing
    Custom(Diag),
}

impl P<'_> {
    // ------------------------------------------------------------------
    // operators
    // ------------------------------------------------------------------
    pub fn parse_operator(&mut self) -> Result<Op, ()> {
        let start = self.pos;
        // read the operator name token
        let name_end = self.read_op_name();
        let name = String::from_utf_lossy(&self.s[start..name_end]).to_string();
        self.pos = name_end;
        // percentile operators: p<number>
        if (name.chars().next() == Some('p')) && name.len() > 1 {
            let digits = &name[1..];
            if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {
                let pct: u32 = digits.parse().unwrap_or(0);
                match self.parse_arg_list(false) {
                    Ok(Some(args)) => {
                        if args.len() != 1 {
                            self.diags.push(Diag {
                                message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                                start,
                                len: name_end - start,
                                label: Some(format!("supplied {} arguments", args.len())),
                                help: vec!["the argument should supply the value to compute the percentile of".to_string()],
                            });
                            return Err(());
                        }
                        return Ok(Op::Percentile(pct, args[0].clone(), Vec::new()));
                    }
                    Ok(None) => {}
                    Err(e) => match e {
                        OpErr::Custom(d) => {
                            self.diags.push(d);
                            return Err(());
                        }
                        OpErr::Graceful => {}
                    },
                }
                // missing paren
                self.diags.push(Diag {
                    message: "expecting a parenthesized argument that supplies the value to compute the percentile of".to_string(),
                    start,
                    len: self.pos - start,
                    label: None,
                    help: vec![],
                });
                return Err(());
            }
        }
        let tok = name.as_str();
        // try operator alternatives in order
        let mut res: Result<Op, OpErr> = Err(OpErr::Graceful);
        match tok {
            "json" => res = self.parse_json(start),
            "logfmt" => res = self.parse_logfmt(start),
            "split" => res = self.parse_split(start),
            "parse" => res = self.parse_parse(start),
            "fields" => res = self.parse_fields(start),
            "where" => res = self.parse_where(start),
            "limit" => res = self.parse_limit(start),
            "total" => res = self.parse_total(start),
            "timeslice" => res = self.parse_timeslice(start),
            "count_distinct" => res = self.parse_count_distinct(start),
            "count" => res = self.parse_count(start),
            "sum" => res = self.parse_agg(start, "sum", "_sum", "find the sum of"),
            "average" | "avg" => res = self.parse_agg(start, "average", "_average", "find the average of"),
            "max" => res = self.parse_agg(start, "max", "_max", "find the maximum of"),
            "min" => res = self.parse_agg(start, "min", "_min", "find the minimum of"),
            "sort" => res = self.parse_sort(start),
            "if" => res = self.parse_if(start),
            "apache" => res = Ok(Op::Alias("apache".to_string())),
            "nginx" => res = Ok(Op::Alias("nginx".to_string())),
            "nginx-access" => res = Ok(Op::Alias("nginx-access".to_string())),
            _ => {}
        }
        match res {
            Ok(op) => Ok(op),
            Err(OpErr::Custom(d)) => {
                self.diags.push(d);
                Err(())
            }
            Err(OpErr::Graceful) => {
                // unknown operator
                let len = (self.s.len() - start).max(1);
                self.diags.push(Diag {
                    message: "Expected an operator".to_string(),
                    start,
                    len,
                    label: None,
                    help: vec![format!("{} is not a valid operator", name)],
                });
                Err(())
            }
        }
    }

    /// reads an operator name: runs until whitespace, `|`, `(` or `)`
    fn read_op_name(&self) -> usize {
        let mut i = self.pos;
        while i < self.s.len() {
            let c = self.s[i];
            if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' || c == b'|' || c == b'(' || c == b')' || c == b',' {
                break;
            }
            i += 1;
        }
        i
    }

    fn at_end(&self) -> bool {
        let mut p = self.pos;
        while p < self.s.len() && (self.s[p] == b' ' || self.s[p] == b'\t' || self.s[p] == b'\r' || self.s[p] == b'\n') {
            p += 1;
        }
        p >= self.s.len()
    }

    fn word(&self) -> Option<String> {
        let mut i = self.pos;
        while i < self.s.len() && (self.s[i].is_ascii_alphanumeric() || self.s[i] == b'_') {
            i += 1;
        }
        if i == self.pos {
            None
        } else {
            Some(String::from_utf_lossy(&self.s[self.pos..i]).to_string())
        }
    }

    // ------------------------------------------------------------------
    // json / logfmt
    // ------------------------------------------------------------------
    fn parse_from_op(&mut self, start: usize, opname: &str, opts: &str) -> Result<Op, OpErr> {
        // optional `from FIELD`
        let mut from = None;
        let save = self.pos;
        self.skip_ws();
        if let Some(w) = self.word() {
            if w == "from" {
                self.skip_ws();
                let fs = self.pos;
                let fe = self.read_field_name();
                if fe == fs {
                    self.diags.push(Diag {
                        message: "unrecognized option, only the 'from' option is available".to_string(),
                        start: fs,
                        len: (self.s.len() - fs).max(1),
                        label: None,
                        help: Vec::new(),
                    });
                    return Err(OpErr::Custom(Diag {
                        message: "unrecognized option, only the 'from' option is available".to_string(),
                        start: fs,
                        len: (self.s.len() - fs).max(1),
                        label: None,
                        help: Vec::new(),
                    }));
                }
                from = Some(String::from_utf_lossy(&self.s[fs..fe]).to_string());
                self.pos = fe;
            }
        }
        if !self.at_end() {
            let s = self.pos;
            let e = self.s.len();
            let d = Diag {
                message: format!("unrecognized option, only the '{}' option is available", opts),
                start: s,
                len: (e - s).max(1),
                label: None,
                help: Vec::new(),
            };
            return Err(OpErr::Custom(d));
        }
        if from.is_none() {
            self.pos = save;
        }
        Ok(if opname == "json" {
            Op::Json { from }
        } else {
            Op::Logfmt { from }
        })
    }

    fn parse_json(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.starts_with("(") {
            return Err(OpErr::Custom(Diag {
                message: "json does not take any parenthesized arguments".to_string(),
                start,
                len: (self.s.len() - start).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        self.parse_from_op(start, "json", "from")
    }

    fn parse_logfmt(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.starts_with("(") {
            return Err(OpErr::Custom(Diag {
                message: "logfmt does not take any parenthesized arguments".to_string(),
                start,
                len: (self.s.len() - start).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        self.parse_from_op(start, "logfmt", "from")
    }

    // ------------------------------------------------------------------
    // split
    // ------------------------------------------------------------------
    fn parse_split(&mut self, start: usize) -> Result<Op, OpErr> {
        let mut field = None;
        let mut sep = None;
        let mut name = None;
        self.skip_ws();
        if self.starts_with("(") {
            self.pos += 1;
            self.skip_ws();
            let fs = self.pos;
            let fe = self.read_field_name();
            if fe == fs {
                return Err(OpErr::Custom(Diag {
                    message: "unhandled input".to_string(),
                    start: fs,
                    len: 1,
                    label: None,
                    help: Vec::new(),
                }));
            }
            field = Some(String::from_utf_lossy(&self.s[fs..fe]).to_string());
            self.pos = fe;
            self.skip_ws();
            if self.peek() != Some(b')') {
                let d = Diag {
                    message: "unterminated function call".to_string(),
                    start: fs,
                    len: (self.s.len() - fs).max(1),
                    label: Some("unterminated function call".to_string()),
                    help: vec!["Insert a right parenthesis to terminate this call".to_string()],
                };
                return Err(OpErr::Custom(d));
            }
            self.pos += 1;
        }
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.eof() || self.peek() == Some(b'|') {
                self.pos = save;
                break;
            }
            if let Some(w) = self.word() {
                if w == "on" {
                    self.skip_ws();
                    let (qs, qe) = match self.parse_quoted() {
                        Some(r) => r,
                        None => {
                            return Err(OpErr::Custom(Diag {
                                message: "unrecognized option, only the 'on' and 'as' options are available".to_string(),
                                start: self.pos,
                                len: (self.s.len() - self.pos).max(1),
                                label: None,
                                help: Vec::new(),
                            }))
                        }
                    };
                    sep = Some(String::from_utf_lossy(&self.s[qs..qe]).to_string());
                    continue;
                }
                if w == "as" {
                    self.skip_ws();
                    let fs = self.pos;
                    let fe = self.read_field_name();
                    name = Some(String::from_utf_lossy(&self.s[fs..fe]).to_string());
                    continue;
                }
            }
            let d = Diag {
                message: "unrecognized option, only the 'on' and 'as' options are available".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            };
            return Err(OpErr::Custom(d));
        }
        Ok(Op::Split { field, sep, name })
    }

    // ------------------------------------------------------------------
    // parse
    // ------------------------------------------------------------------
    fn parse_parse(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        let mut mode = ParseMode::Plain;
        if let Some(w) = self.word() {
            if w == "regex" {
                mode = ParseMode::Regex;
                self.skip_ws();
            } else if w == "from" || w == "as" || w == "nodrop" || w == "noconvert" {
                // parse without a pattern -> unrecognized option error
                return Err(OpErr::Custom(Diag {
                    message: "unrecognized option, only the 'from' and 'nodrop' options are available".to_string(),
                    start: self.pos,
                    len: (self.s.len() - self.pos).max(1),
                    label: None,
                    help: Vec::new(),
                }));
            }
        }
        let (qs, qe) = match self.parse_quoted() {
            Some(r) => r,
            None => {
                return Err(OpErr::Graceful);
            }
        };
        let pattern = unquote(&self.s[qs..qe], q == b'"');
        let mut from = None;
        let mut names = Vec::new();
        let mut nodrop = false;
        let mut noconvert = false;
        let mut seen_as = false;
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.eof() || self.peek() == Some(b'|') {
                self.pos = save;
                break;
            }
            if let Some(w) = self.word() {
                if w == "from" && !seen_as {
                    self.skip_ws();
                    let fs = self.pos;
                    let fe = self.read_field_name();
                    from = Some(String::from_utf_lossy(&self.s[fs..fe]).to_string());
                    self.pos = fe;
                    continue;
                }
                if w == "as" {
                    seen_as = true;
                    loop {
                        self.skip_ws();
                        let fs = self.pos;
                        let fe = self.read_field_name();
                        if fe == fs {
                            break;
                        }
                        names.push(String::from_utf_lossy(&self.s[fs..fe]).to_string());
                        self.pos = fe;
                        self.skip_ws();
                        if self.peek() == Some(b',') {
                            self.pos += 1;
                            continue;
                        }
                        break;
                    }
                    continue;
                }
                if seen_as && w == "nodrop" {
                    nodrop = true;
                    continue;
                }
                if seen_as && w == "noconvert" {
                    noconvert = true;
                    continue;
                }
                if !seen_as && w == "nodrop" {
                    nodrop = true;
                    continue;
                }
            }
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the 'from' and 'nodrop' options are available".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        Ok(Op::Parse {
            mode,
            pattern,
            from,
            names,
            nodrop,
            noconvert,
        })
    }

    // ------------------------------------------------------------------
    // fields
    // ------------------------------------------------------------------
    fn parse_fields(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.starts_with("(") {
            // fields(...) -> unterminated function call
            return Err(OpErr::Custom(Diag {
                message: "unterminated function call".to_string(),
                start,
                len: (self.s.len() - start).max(1),
                label: Some("unterminated function call".to_string()),
                help: vec!["Insert a right parenthesis to terminate this call".to_string()],
            }));
        }
        let mut mode = FieldsMode::Only;
        if let Some(w) = self.word() {
            match w.as_str() {
                "only" | "+" => {
                    self.pos += w.len();
                    mode = FieldsMode::Only;
                }
                "except" | "-" => {
                    self.pos += w.len();
                    mode = FieldsMode::Except;
                }
                _ => {}
            }
        }
        let mut names = Vec::new();
        loop {
            self.skip_ws();
            let fs = self.pos;
            let fe = self.read_field_name();
            if fe == fs {
                break;
            }
            names.push(String::from_utf_lossy(&self.s[fs..fe]).to_string());
            self.pos = fe;
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
                continue;
            }
            break;
        }
        if !self.at_end() {
            return Err(OpErr::Graceful);
        }
        Ok(Op::Fields { mode, names })
    }

    // ------------------------------------------------------------------
    // where
    // ------------------------------------------------------------------
    fn parse_where(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.eof() || self.peek() == Some(b'|') {
            let d = Diag {
                message: "Expected an expression".to_string(),
                start,
                len: "where".len(),
                label: Some("No condition provided for this 'where'".to_string()),
                help: vec![
                    "Insert an expression whose result determines whether a record should be passed downstream".to_string(),
                    "example: where duration > 100".to_string(),
                ],
            };
            return Err(OpErr::Custom(d));
        }
        let e = self.parse_expr(false)?;
        if !self.at_end() {
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the condition can be specified".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        Ok(Op::Where(e))
    }

    // ------------------------------------------------------------------
    // limit
    // ------------------------------------------------------------------
    fn parse_limit(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.starts_with("(") {
            return Err(OpErr::Custom(Diag {
                message: "limit does not take any parenthesized arguments".to_string(),
                start,
                len: (self.s.len() - start).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        // optional number
        let save = self.pos;
        let ns = self.pos;
        let mut i = self.pos;
        if i < self.s.len() && self.s[i] == b'-' {
            i += 1;
        }
        let ds = i;
        while i < self.s.len() && self.s[i].is_ascii_digit() {
            i += 1;
        }
        if i > ds {
            self.pos = i;
            if !self.at_end() {
                return Err(OpErr::Custom(Diag {
                    message: "unrecognized option, only the numeric limit can be specified".to_string(),
                    start: self.pos,
                    len: (self.s.len() - self.pos).max(1),
                    label: None,
                    help: Vec::new(),
                }));
            }
            let txt = String::from_utf_lossy(&self.s[ns..i]).to_string();
            let n: i64 = txt.parse().unwrap_or(0);
            if n == 0 {
                self.diags.push(Diag {
                    message: format!("Limit must be a non-zero integer, found {}", n),
                    start: ns,
                    len: i - ns,
                    label: Some("Zero is not allowed".to_string()),
                    help: vec!["Try a negative number to get the last N rows".to_string()],
                });
                return Err(OpErr::Custom(Diag {
                    message: format!("Limit must be a non-zero integer, found {}", n),
                    start: ns,
                    len: i - ns,
                    label: Some("Zero is not allowed".to_string()),
                    help: vec!["Try a negative number to get the last N rows".to_string()],
                }));
            }
            return Ok(Op::Limit(n));
        }
        self.pos = save;
        if !self.at_end() {
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the numeric limit can be specified".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        Ok(Op::Limit(i64::MAX))
    }

    // ------------------------------------------------------------------
    // aggregate operators
    // ------------------------------------------------------------------
    fn parse_total(&mut self, start: usize) -> Result<Op, OpErr> {
        let args = self.require_arg_list(start, "supplies the value to sum")?;
        if args.len() != 1 {
            return Err(OpErr::Custom(Diag {
                message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                start,
                len: 5,
                label: Some(format!("supplied {} arguments", args.len())),
                help: vec!["the argument should supply the value to sum".to_string()],
            }));
        }
        let name = self.parse_as_clause()?.unwrap_or_else(|| "_total".to_string());
        if !self.at_end() {
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the 'as' option is available".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        Ok(Op::Total(args[0].clone(), name))
    }

    fn parse_if(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.peek() != Some(b'(') {
            return Err(OpErr::Graceful);
        }
        let args = self.require_arg_list(start, "the 'if' operator")?;
        if args.len() != 3 {
            return Err(OpErr::Custom(Diag {
                message: "the 'if' operator expects exactly 3 arguments, the condition, value-if-true, and value-if-false".to_string(),
                start: start + 2,
                len: (self.s.len() - start - 2).max(1),
                label: Some(format!("supplied {} arguments", args.len())),
                help: Vec::new(),
            }));
        }
        let name = self.parse_as_clause()?.unwrap_or_else(|| "_if".to_string());
        if !self.at_end() {
            return Err(OpErr::Graceful);
        }
        Ok(Op::IfOp(args, name))
    }

    fn parse_timeslice(&mut self, start: usize) -> Result<Op, OpErr> {
        let args = self.require_arg_list(start, "supplies the timestamp to truncate")?;
        if args.len() != 1 {
            return Err(OpErr::Custom(Diag {
                message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                start,
                len: 9,
                label: Some(format!("supplied {} arguments", args.len())),
                help: vec!["the argument should supply the timestamp to truncate".to_string()],
            }));
        }
        self.skip_ws();
        // duration
        let mut i = self.pos;
        let ds = i;
        while i < self.s.len() && self.s[i].is_ascii_digit() {
            i += 1;
        }
        if i == ds {
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the 'as' option is available".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        let num: u64 = String::from_utf_lossy(&self.s[ds..i]).to_string().parse().unwrap_or(0);
        let us = i;
        while i < self.s.len() && self.s[i].is_ascii_alphabetic() {
            i += 1;
        }
        let unit = String::from_utf_lossy(&self.s[us..i]).to_string();
        let mult: f64 = match unit.as_str() {
            "ns" => 1e-9,
            "us" => 1e-6,
            "ms" => 1e-3,
            "s" => 1.0,
            "m" => 60.0,
            "h" => 3600.0,
            "d" => 86400.0,
            "w" => 604800.0,
            _ => {
                return Err(OpErr::Custom(Diag {
                    message: "unrecognized option, only the 'as' option is available".to_string(),
                    start: us,
                    len: (self.s.len() - us).max(1),
                    label: None,
                    help: Vec::new(),
                }))
            }
        };
        self.pos = i;
        let name = self.parse_as_clause()?.unwrap_or_else(|| "_timeslice".to_string());
        if !self.at_end() {
            return Err(OpErr::Custom(Diag {
                message: "unrecognized option, only the 'as' option is available".to_string(),
                start: self.pos,
                len: (self.s.len() - self.pos).max(1),
                label: None,
                help: Vec::new(),
            }));
        }
        Ok(Op::Timeslice {
            expr: args[0].clone(),
            seconds: (num as f64) * mult,
            nanos: num,
            name,
        })
    }

    fn parse_count(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        let cond = if self.peek() == Some(b'(') {
            Some(self.require_arg_list(start, "the condition to count")?)
        } else {
            None
        };
        let name = self.parse_as_clause()?;
        let by = self.parse_by_clause(1)?;
        if !self.at_end() {
            return Err(OpErr::Graceful);
        }
        let cond_expr = match cond {
            Some(args) => {
                if args.len() != 1 {
                    return Err(OpErr::Custom(Diag {
                        message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                        start,
                        len: 5,
                        label: Some(format!("supplied {} arguments", args.len())),
                        help: vec!["the argument should supply the condition to count".to_string()],
                    }));
                }
                Some(args[0].clone())
            }
            None => None,
        };
        Ok(Op::Count { cond: cond_expr, name, by })
    }

    fn parse_count_distinct(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        if self.peek() == Some(b'(') {
            let args = self.require_arg_list(start, "the value to count")?;
            if args.len() != 1 {
                return Err(OpErr::Custom(Diag {
                    message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                    start,
                    len: 14,
                    label: Some(format!("supplied {} arguments", args.len())),
                    help: vec!["the argument should supply the value to count".to_string()],
                }));
            }
            let by = self.parse_by_clause(0)?;
            if !self.at_end() {
                return Err(OpErr::Graceful);
            }
            return Ok(Op::CountDistinct(args[0].clone(), by));
        }
        // no parens
        Err(OpErr::Custom(Diag {
            message: "Expecting an expression to count".to_string(),
            start,
            len: 14,
            label: None,
            help: Vec::new(),
        }))
    }

    fn parse_agg(&mut self, start: usize, _name: &str, _default: &str, help: &'static str) -> Result<Op, OpErr> {
        let args = self.require_arg_list(start, help)?;
        if args.len() != 1 {
            return Err(OpErr::Custom(Diag {
                message: format!("this operator takes 1 argument, but {} were supplied", args.len()),
                start,
                len: self.pos - start,
                label: Some(format!("supplied {} arguments", args.len())),
                help: vec![format!("the argument should {}", help)],
            }));
        }
        let name = self.parse_as_clause()?;
        let by = self.parse_by_clause(0)?;
        if !self.at_end() {
            return Err(OpErr::Graceful);
        }
        let e = args[0].clone();
        Ok(match _name {
            "sum" => Op::Sum(e, name, by),
            "average" => Op::Average(e, name, by),
            "max" => Op::Max(e, name, by),
            _ => Op::Min(e, name, by),
        })
    }

    fn parse_sort(&mut self, start: usize) -> Result<Op, OpErr> {
        self.skip_ws();
        let mut keys = Vec::new();
        let mut dir = SortDir::Asc;
        let save = self.pos;
        if let Some(w) = self.word() {
            if w == "by" {
                self.pos += 2;
                loop {
                    self.skip_ws();
                    let e = match self.parse_expr(false) {
                        Ok(e) => e,
                        Err(_) => break,
                    };
                    keys.push(e);
                    self.skip_ws();
                    if self.peek() == Some(b',') {
                        self.pos += 1;
                        continue;
                    }
                    break;
                }
                self.skip_ws();
                if let Some(w) = self.word() {
                    if w == "asc" {
                        dir = SortDir::Asc;
                    } else if w == "desc" {
                        dir = SortDir::Desc;
                    }
                }
            } else {
                self.pos = save;
            }
        }
        if !self.at_end() {
            self.pos = save;
            return Err(OpErr::Graceful);
        }
        Ok(Op::Sort(keys, dir))
    }

    // ------------------------------------------------------------------
    // argument lists
    // ------------------------------------------------------------------
    fn require_arg_list(&mut self, start: usize, help: &str) -> Result<Vec<Expr>, OpErr> {
        self.skip_ws();
        if self.peek() != Some(b'(') {
            let d = Diag {
                message: format!("expecting a parenthesized argument that {}", help),
                start,
                len: (self.s.len() - start).max(1),
                label: None,
                help: Vec::new(),
            };
            return Err(OpErr::Custom(d));
        }
        let lparen = self.pos;
        self.pos += 1;
        let mut args = Vec::new();
        let mut paren = 1;
        loop {
            self.skip_ws();
            if self.eof() {
                let d = Diag {
                    message: "unterminated function call".to_string(),
                    start: lparen,
                    len: (self.s.len() - lparen).max(1),
                    label: Some("unterminated function call".to_string()),
                    help: vec!["Insert a right parenthesis to terminate this call".to_string()],
                };
                if args.is_empty() {
                    self.diags.push(Diag {
                        message: "this operator takes 1 argument, but 0 were supplied".to_string(),
                        start: lparen,
                        len: 0,
                        label: Some("supplied 0 arguments".to_string()),
                        help: vec![format!("the argument should {}", help)],
                    });
                }
                return Err(OpErr::Custom(d));
            }
            if self.peek() == Some(b')') {
                if args.is_empty() {
                    return Err(OpErr::Custom(Diag {
                        message: "this operator takes 1 argument, but 0 were supplied".to_string(),
                        start: self.pos,
                        len: 0,
                        label: Some("supplied 0 arguments".to_string()),
                        help: vec![format!("the argument should {}", help)],
                    }));
                }
                self.pos += 1;
                break;
            }
            match self.parse_expr(true) {
                Ok(e) => args.push(e),
                Err(_) => {
                    let d = Diag {
                        message: "unhandled input".to_string(),
                        start: self.pos,
                        len: (self.s.len() - self.pos).max(1),
                        label: None,
                        help: Vec::new(),
                    };
                    return Err(OpErr::Custom(d));
                }
            }
            self.skip_ws();
            if self.peek() == Some(b',') {
                self.pos += 1;
                continue;
            }
            if self.peek() == Some(b')') {
                self.pos += 1;
                break;
            }
            let d = Diag {
                message: "unterminated function call".to_string(),
                start: lparen,
                len: (self.s.len() - lparen).max(1),
                label: Some("unterminated function call".to_string()),
                help: vec!["Insert a right parenthesis to terminate this call".to_string()],
            };
            return Err(OpErr::Custom(d));
        }
        let _ = paren;
        Ok(args)
    }

    fn parse_arg_list(&mut self, _required: bool) -> Result<Option<Vec<Expr>>, OpErr> {
        let save = self.pos;
        self.skip_ws();
        if self.peek() != Some(b'(') {
            self.pos = save;
            return Ok(None);
        }
        match self.require_arg_list(save, "argument") {
            Ok(a) => Ok(Some(a)),
            Err(e) => Err(e),
        }
    }

    fn parse_as_clause(&mut self) -> Result<Option<String>, OpErr> {
        let save = self.pos;
        self.skip_ws();
        if let Some(w) = self.word() {
            if w == "as" {
                self.skip_ws();
                let fs = self.pos;
                let fe = self.read_field_name();
                if fe == fs {
                    return Err(OpErr::Graceful);
                }
                self.pos = fe;
                return Ok(Some(String::from_utf_lossy(&self.s[fs..fe]).to_string()));
            }
        }
        self.pos = save;
        Ok(None)
    }

    /// parses `by expr(, expr)*`; if none is present returns an empty vec
    fn parse_by_clause(&mut self, copies: usize) -> Result<Vec<Expr>, OpErr> {
        let save = self.pos;
        self.skip_ws();
        if let Some(w) = self.word() {
            if w == "by" {
                let mut out = Vec::new();
                loop {
                    self.skip_ws();
                    if self.eof() || self.peek() == Some(b'|') {
                        return Ok(out);
                    }
                    match self.parse_expr_expr(copies) {
                        Ok(e) => out.push(e),
                        Err(_) => return Ok(out),
                    }
                    self.skip_ws();
                    if self.peek() == Some(b',') {
                        self.pos += 1;
                        continue;
                    }
                    break;
                }
                return Ok(out);
            }
        }
        self.pos = save;
        Ok(Vec::new())
    }

    /// like parse_expr but reports `expecting an expression` when it fails
    fn parse_expr_expr(&mut self, copies: usize) -> Result<Expr, ()> {
        let start = self.pos;
        match self.parse_expr(true) {
            Ok(e) => Ok(e),
            Err(_) => {
                let msg = if self.diags.items.len() > self.last_expr_diag {
                    String::new()
                } else {
                    String::new()
                };
                let _ = msg;
                let len = (self.s.len() - start).max(1);
                self.diags.push_n(
                    Diag {
                        message: "expecting an expression".to_string(),
                        start,
                        len,
                        label: None,
                        help: Vec::new(),
                    },
                    copies.max(1),
                );
                Err(())
            }
        }
    }

    pub last_expr_diag: usize,

    // ------------------------------------------------------------------
    // expressions
    // ------------------------------------------------------------------
    pub fn parse_expr(&mut self, in_args: bool) -> Result<Expr, ()> {
        self.parse_or(in_args)
    }

    fn parse_or(&mut self, in_args: bool) -> Result<Expr, ()> {
        let mut l = self.parse_and(in_args)?;
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.starts_with_ci("or") && self.is_word_end(2) {
                self.pos += 2;
                let r = self.parse_and(in_args)?;
                l = Expr::Bin(BinOp::Or, Box::new(l), Box::new(r));
            } else if self.starts_with("||") {
                self.pos += 2;
                let r = self.parse_and(in_args)?;
                l = Expr::Bin(BinOp::Or, Box::new(l), Box::new(r));
            } else {
                self.pos = save;
                break;
            }
        }
        Ok(l)
    }

    fn parse_and(&mut self, in_args: bool) -> Result<Expr, ()> {
        let mut l = self.parse_cmp(in_args)?;
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.starts_with_ci("and") && self.is_word_end(3) {
                self.pos += 3;
                let r = self.parse_cmp(in_args)?;
                l = Expr::Bin(BinOp::And, Box::new(l), Box::new(r));
            } else if self.starts_with("&&") {
                self.pos += 2;
                let r = self.parse_cmp(in_args)?;
                l = Expr::Bin(BinOp::And, Box::new(l), Box::new(r));
            } else {
                self.pos = save;
                break;
            }
        }
        Ok(l)
    }

    fn parse_cmp(&mut self, in_args: bool) -> Result<Expr, ()> {
        let l = self.parse_add(in_args)?;
        self.skip_ws();
        let op = if self.starts_with("==") {
            Some((BinOp::Eq, 2))
        } else if self.starts_with("!=") {
            Some((BinOp::Ne, 2))
        } else if self.starts_with("<>") {
            Some((BinOp::Ne, 2))
        } else if self.starts_with("<=") {
            Some((BinOp::Le, 2))
        } else if self.starts_with(">=") {
            Some((BinOp::Ge, 2))
        } else if self.starts_with("<") {
            Some((BinOp::Lt, 1))
        } else if self.starts_with(">") {
            Some((BinOp::Gt, 1))
        } else {
            None
        };
        if let Some((op, len)) = op {
            self.pos += len;
            self.skip_ws();
            if self.eof() || self.peek() == Some(b',') || self.peek() == Some(b')') || self.peek() == Some(b'|') {
                let len = (self.s.len() - self.pos).max(1);
                self.diags.push(Diag {
                    message: "expecting the right-hand-side of the comparison".to_string(),
                    start: self.pos,
                    len,
                    label: None,
                    help: Vec::new(),
                });
                return Err(());
            }
            let r = self.parse_add(in_args)?;
            return Ok(Expr::Bin(op, Box::new(l), Box::new(r)));
        }
        Ok(l)
    }

    fn parse_add(&mut self, in_args: bool) -> Result<Expr, ()> {
        let mut l = self.parse_mul(in_args)?;
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.peek() == Some(b'+') {
                self.pos += 1;
                let r = self.parse_mul(in_args)?;
                l = Expr::Bin(BinOp::Add, Box::new(l), Box::new(r));
            } else if self.peek() == Some(b'-') {
                self.pos += 1;
                let r = self.parse_mul(in_args)?;
                l = Expr::Bin(BinOp::Sub, Box::new(l), Box::new(r));
            } else {
                self.pos = save;
                break;
            }
        }
        Ok(l)
    }

    fn parse_mul(&mut self, in_args: bool) -> Result<Expr, ()> {
        let mut l = self.parse_unary(in_args)?;
        loop {
            let save = self.pos;
            self.skip_ws();
            if self.peek() == Some(b'*') {
                self.pos += 1;
                let r = self.parse_unary(in_args)?;
                l = Expr::Bin(BinOp::Mul, Box::new(l), Box::new(r));
            } else if self.peek() == Some(b'/') {
                self.pos += 1;
                let r = self.parse_unary(in_args)?;
                l = Expr::Bin(BinOp::Div, Box::new(l), Box::new(r));
            } else {
                self.pos = save;
                break;
            }
        }
        Ok(l)
    }

    fn parse_unary(&mut self, in_args: bool) -> Result<Expr, ()> {
        self.skip_ws();
        if self.peek() == Some(b'!') {
            self.pos += 1;
            let e = self.parse_unary(in_args)?;
            return Ok(Expr::Not(Box::new(e)));
        }
        self.parse_primary(in_args)
    }

    fn parse_primary(&mut self, in_args: bool) -> Result<Expr, ()> {
        self.skip_ws();
        match self.peek() {
            None => Err(()),
            Some(b'(') => {
                let start = self.pos;
                self.pos += 1;
                let e = self.parse_expr(in_args)?;
                self.skip_ws();
                if self.peek() == Some(b')') {
                    self.pos += 1;
                    Ok(e)
                } else {
                    self.diags.push(Diag {
                        message: "unterminated parenthesized expression".to_string(),
                        start,
                        len: (self.s.len() - start).max(1),
                        label: Some("unterminated parenthesized expression".to_string()),
                        help: vec!["Insert a right parenthesis to terminate this expression".to_string()],
                    });
                    Err(())
                }
            }
            Some(b'"') | Some(b'\'') => {
                let start = self.pos;
                match self.parse_quoted() {
                    Some((qs, qe)) => {
                        let q = self.s[qs];
                        let s = unquote(&self.s[qs..qe], q == b'"');
                        let _ = start;
                        Ok(Expr::Lit(Value::Str(s)))
                    }
                    None => {
                        self.unterminated_string(start);
                        Err(())
                    }
                }
            }
            Some(c) if c.is_ascii_digit() => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c.is_ascii_digit() {
                        self.pos += 1;
                    } else {
                        break;
                    }
                }
                let txt = String::from_utf_lossy(&self.s[start..self.pos]).to_string();
                match txt.parse::<i64>() {
                    Ok(n) => Ok(Expr::Lit(Value::Num(n as f64))),
                    Err(_) => {
                        let d = Diag {
                            message: "unhandled input".to_string(),
                            start,
                            len: self.pos - start,
                            label: None,
                            help: Vec::new(),
                        };
                        self.diags.push(d.clone());
                        Err(())
                    }
                }
            }
            Some(c) if is_ident_start(c) => {
                let start = self.pos;
                // function call?
                let mut i = self.pos;
                while i < self.s.len() && (self.s[i].is_ascii_alphanumeric() || self.s[i] == b'_') {
                    i += 1;
                }
                let word = String::from_utf_lossy(&self.s[start..i]).to_string();
                let mut j = i;
                while j < self.s.len() && (self.s[j] == b' ' || self.s[j] == b'\t') {
                    j += 1;
                }
                if j < self.s.len() && self.s[j] == b'(' && crate::funcs::is_func(&word) {
                    self.pos = j + 1;
                    let mut args = Vec::new();
                    loop {
                        self.skip_ws();
                        if self.eof() {
                            self.diags.push(Diag {
                                message: "unterminated function call".to_string(),
                                start,
                                len: (self.s.len() - start).max(1),
                                label: Some("unterminated function call".to_string()),
                                help: vec!["Insert a right parenthesis to terminate this call".to_string()],
                            });
                            return Err(());
                        }
                        if self.peek() == Some(b')') {
                            self.pos += 1;
                            break;
                        }
                        let a = self.parse_expr(true)?;
                        args.push(a);
                        self.skip_ws();
                        if self.peek() == Some(b',') {
                            self.pos += 1;
                            continue;
                        }
                        if self.peek() == Some(b')') {
                            self.pos += 1;
                            break;
                        }
                        self.diags.push(Diag {
                            message: "unterminated function call".to_string(),
                            start,
                            len: (self.s.len() - start).max(1),
                            label: Some("unterminated function call".to_string()),
                            help: vec!["Insert a right parenthesis to terminate this call".to_string()],
                        });
                        return Err(());
                    }
                    return Ok(Expr::Func(word, args));
                }
                // field path
                let end = self.read_path();
                if end == start {
                    let d = Diag {
                        message: "unhandled input".to_string(),
                        start,
                        len: (self.s.len() - start).max(1),
                        label: None,
                        help: Vec::new(),
                    };
                    self.diags.push(d);
                    return Err(());
                }
                let src = String::from_utf_lossy(&self.s[start..end]).to_string();
                let parts = parse_path_src(&src);
                self.pos = end;
                Ok(Expr::Path(Path { parts, src }))
            }
            _ => {
                let d = Diag {
                    message: "unhandled input".to_string(),
                    start: self.pos,
                    len: (self.s.len() - self.pos).max(1),
                    label: None,
                    help: Vec::new(),
                };
                self.diags.push(d);
                Err(())
            }
        }
    }

    fn unterminated_string(&mut self, start: usize) {
        let q = self.s[start];
        let end = if self.paren_depth > 0 {
            let mut i = start;
            while i < self.s.len() && self.s[i] != b')' {
                i += 1;
            }
            i
        } else {
            self.s.len()
        };
        self.diags.push(Diag {
            message: if q == b'"' {
                "unterminated double quoted string".to_string()
            } else {
                "unterminated single quoted string".to_string()
            },
            start,
            len: (end - start).max(1),
            label: None,
            help: vec![format!(
                "Insert a {} quote ({}) to terminate this string",
                if q == b'"' { "double" } else { "single" },
                q as char
            )],
        });
    }

    /// reads a quoted string, returns (start,end) byte indices of the quotes
    pub fn parse_quoted(&mut self) -> Option<(usize, usize)> {
        self.skip_ws();
        let start = self.pos;
        let q = match self.peek() {
            Some(c @ (b'"' | b'\'')) => c,
            _ => return None,
        };
        self.pos += 1;
        loop {
            match self.peek() {
                None => return None,
                Some(b'\\') => {
                    self.pos += 1;
                    if self.peek().is_some() {
                        self.pos += 1;
                    }
                }
                Some(c) if c == q => {
                    self.pos += 1;
                    return Some((start, self.pos));
                }
                Some(_) => {
                    self.pos += 1;
                }
            }
        }
    }

    /// reads a field name, possibly escaped with ["..."], returns the end index
    pub fn read_field_name(&mut self) -> usize {
        self.skip_ws();
        let start = self.pos;
        if self.starts_with("[\"") {
            match self.parse_quoted() {
                Some((qs, qe)) => {
                    let mut i = qe;
                    if i < self.s.len() && self.s[i] == b']' {
                        i += 1;
                    }
                    return i;
                }
                None => return start,
            }
        }
        let mut i = self.pos;
        while i < self.s.len() {
            let c = self.s[i];
            if is_ident_char(c) {
                i += 1;
            } else {
                break;
            }
        }
        if i > start {
            // trailing indices / nested paths
            loop {
                if i < self.s.len() && self.s[i] == b'[' {
                    let mut j = i + 1;
                    if j < self.s.len() && self.s[j] == b'-' {
                        j += 1;
                    }
                    let mut ok = false;
                    while j < self.s.len() && self.s[j].is_ascii_digit() {
                        ok = true;
                        j += 1;
                    }
                    if ok && j < self.s.len() && self.s[j] == b']' {
                        i = j + 1;
                        continue;
                    }
                    break;
                }
                break;
            }
        }
        i
    }

    /// reads a full path expression (name, .name, [idx]) returning the end index
    fn read_path(&mut self) -> usize {
        let mut i = self.pos;
        while i < self.s.len() && (self.s[i].is_ascii_alphanumeric() || self.s[i] == b'_' || self.s[i] >= 0x80) {
            i += 1;
        }
        if i == self.pos {
            return i;
        }
        loop {
            if i < self.s.len() && self.s[i] == b'.' && i + 1 < self.s.len() && (self.s[i + 1].is_ascii_alphabetic() || self.s[i + 1] == b'_' || self.s[i + 1] >= 0x80) {
                i += 1;
                while i < self.s.len() && (self.s[i].is_ascii_alphanumeric() || self.s[i] == b'_' || self.s[i] >= 0x80) {
                    i += 1;
                }
                continue;
            }
            if i < self.s.len() && self.s[i] == b'[' {
                let mut j = i + 1;
                if j < self.s.len() && self.s[j] == b'-' {
                    j += 1;
                }
                let mut ok = false;
                while j < self.s.len() && self.s[j].is_ascii_digit() {
                    ok = true;
                    j += 1;
                }
                if ok && j < self.s.len() && self.s[j] == b']' {
                    i = j + 1;
                    continue;
                }
                break;
            }
            break;
        }
        i
    }
}

pub fn unquote(bytes: &[u8], double: bool) -> String {
    let inner = &bytes[1..bytes.len() - 1];
    let mut out = String::new();
    let mut i = 0;
    while i < inner.len() {
        if inner[i] == b'\\' && i + 1 < inner.len() {
            let c = inner[i + 1];
            out.push(match c {
                b'n' => '\n',
                b't' => '\t',
                b'r' => '\r',
                b'\\' => '\\',
                b'"' => '"',
                b'\'' => '\'',
                other => other as char,
            });
            i += 2;
        } else {
            let l = crate::query::utf8_len(&inner[i..]);
            out.push_str(&String::from_utf_lossy(&inner[i..i + l]));
            i += l;
        }
    }
    let _ = double;
    out
}

pub fn parse_path_src(src: &str) -> Vec<PathPart> {
    let b: Vec<char> = src.chars().collect();
    let mut i = 0usize;
    let mut out = Vec::new();
    // optional leading ["..."]
    if b.len() >= 2 && b[0] == b'[' && b[1] == b'"' {
        // find the closing quote
        let mut j = 2;
        let mut s = String::new();
        while j < b.len() && b[j] != b'"' {
            s.push(b[j]);
            j += 1;
        }
        out.push(PathPart::Key(s));
        i = if j + 1 < b.len() { j + 2 } else { b.len() };
    }
    while i < b.len() {
        if b[i] == '.' {
            i += 1;
            let start = i;
            while i < b.len() && (b[i].is_alphanumeric() || b[i] == '_' || b[i] as u32 >= 0x80) {
                i += 1;
            }
            out.push(PathPart::Key(b[start..i].iter().collect()));
            continue;
        }
        if b[i] == '[' {
            i += 1;
            let mut neg = false;
            if i < b.len() && b[i] == '-' {
                neg = true;
                i += 1;
            }
            let start = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            let n: i64 = b[start..i].iter().collect::<String>().parse().unwrap_or(0);
            out.push(PathPart::Index(if neg { -n } else { n }));
            if i < b.len() && b[i] == b']' {
                i += 1;
            }
            continue;
        }
        let start = i;
        while i < b.len() && (b[i].is_alphanumeric() || b[i] == '_' || b[i] as u32 >= 0x80) {
            i += 1;
        }
        if i == start {
            i += 1;
        } else {
            out.push(PathPart::Key(b[start..i].iter().collect()));
        }
    }
    out
}
