//! record type used in the pipeline

use crate::value::Value;
use std::collections::BTreeMap;

#[derive(Clone, Debug, PartialEq)]
pub enum Record {
    Raw(String),
    Fields(BTreeMap<String, Value>),
}

impl Record {
    pub fn get(&self, key: &str) -> Option<Value> {
        match self {
            Record::Raw(_) => None,
            Record::Fields(m) => m.get(key).cloned(),
        }
    }
    pub fn set(&mut self, key: String, v: Value) {
        if let Record::Raw(_) = self {
            *self = Record::Fields(BTreeMap::new());
        }
        if let Record::Fields(m) = self {
            m.insert(key, v);
        }
    }
    pub fn is_raw(&self) -> bool {
        matches!(self, Record::Raw(_))
    }
    pub fn raw(&self) -> Option<&String> {
        match self {
            Record::Raw(s) => Some(s),
            _ => None,
        }
    }
    pub fn fields(&self) -> &BTreeMap<String, Value> {
        static EMPTY: BTreeMap<String, Value> = BTreeMap::new();
        match self {
            Record::Raw(_) => &EMPTY,
            Record::Fields(m) => m,
        }
    }
}
