{"command": "cat > src/eval.rs <<'RSEOF'
//! Expression evaluation

use crate::query::*;
use crate::value::*;
use crate::record::Record;

#[derive(Debug, Clone, PartialEq)]
pub enum AgrError {
    MissingKey(String),
    ExpectedObject(String),
    ExpectedArray(String),
    IndexOutOfRange(i64),
    UnknownFunction(String),
    ParseDate(String),
    ParseHex(String),
    Other(String),
}

impl std::fmt::Display for AgrError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AgrError::MissingKey(k) => write!(f, "No value for key \"{}\"", k),
            AgrError::ExpectedObject(v) => write!(f, "Expected object, found {}", v),
            AgrError::ExpectedArray(v) => write!(f, "Expected array, found {}", v),
            AgrError::IndexOutOfRange(i) => write!(f, "Index {} out of range", i),
            AgrError::UnknownFunction(f2) => write!(f, "Unknown function {}", f2),
            AgrError::ParseDate(s) => write!(f, "The 'parseDate' function failed with the error: {}", s),
            AgrError::ParseHex(s) => write!(f, "The 'parseHex' function failed with the error: {}", s),
            AgrError::Other(s) => write!(f, "{}", s),
        }
    }
}

pub type EResult<T> = Result<T, AgrError>;

/// Resolve a field path within a record
pub fn resolve_path(rec: &Record, parts: &[PathPart]) -> EResult<Option<Value>> {
    if parts.is_empty() {
        return Ok(None);
    }
    let mut cur: Option<Value> = match &parts[0] {
        PathPart::Key(k) => rec.get(k),
        PathPart::Index(_) => None,
    };
    if cur.is_none() {
        return match &parts[0] {
            PathPart::Key(k) => Err(AgrError::MissingKey(k.clone())),
            PathPart::Index(i) => Err(AgrError::IndexOutOfRange(*i)),
        };
    }
    for p in &parts[1..] {
        let c = cur.unwrap();
        cur = match (p, c) {
            (PathPart::Key(k), Value::Map(m)) => m.get(k).cloned(),
            (PathPart::Index(i), Value::Arr(a)) => {
                let n = a.len() as i64;
                let idx = if *i < 0 { n + *i } else { *i };
                if idx < 0 || idx >= n {
                    return Err(AgrError::IndexOutOfRange(*i));
                }
                Some(a[idx as usize].clone())
            }
            (_, other) => match p {
                PathPart::Key(_) => Err(AgrError::ExpectedObject(other.display())),
                PathPart::Index(_) => Err(AgrError::ExpectedArray(other.display())),
            },
        };
        if cur.is_none() {
            // missing key inside a map -> error
            return Err(AgrError::MissingKey(path_src(parts)));
        }
    }
    Ok(cur)
}

fn path_src(parts: &[PathPart]) -> String {
    let mut s = String::new();
    for (i, p) in parts.iter().enumerate() {
        match p {
            PathPart::Key(k) => {
                if i == 0 {
                    s.push_str(k);
                } else {
                    s.push('.');
                    s.push_str(k);
                }
            }
            PathPart::Index(idx) => {
                s.push_str(&format!("[{}]", idx));
            }
        }
    }
    s
}

pub fn eval(e: &Expr, rec: &Record) -> EResult<Value> {
    match e {
        Expr::Lit(v) => Ok(v.clone()),
        Expr::Path(p) => match resolve_path(rec, &p.parts)? {
            Some(v) => Ok(v),
            None => Ok(Value::Null),
        },
        Expr::Not(e) => Ok(Value::Bool(!truthy(&eval(e, rec)?))),
        Expr::Bin(op, l, r) => {
            match op {
                BinOp::And => {
                    let lv = eval(l, rec)?;
                    if !truthy(&lv) {
                        return Ok(Value::Bool(false));
                    }
                    let rv = eval(r, rec)?;
                    Ok(Value::Bool(truthy(&rv)))
                }
                BinOp::Or => {
                    let lv = eval(l, rec)?;
                    if truthy(&lv) {
                        return Ok(Value::Bool(true));
                    }
                    let rv = eval(r, rec)?;
                    Ok(Value::Bool(truthy(&rv)))
                }
                BinOp::Eq | BinOp::Ne => {
                    let lv = eval(l, rec)?;
                    let rv = eval(r, rec)?;
                    let eq = values_equal(&lv, &rv);
                    Ok(Value::Bool(if *op == BinOp::Eq { eq } else { !eq }))
                }
                _ => {
                    let lv = eval(l, rec)?;
                    let rv = eval(r, rec)?;
                    Ok(apply_bin(*op, &lv, &rv))
                }
            }
        }
        Expr::Func(name, args) => call_func(name, args, rec),
    }
}

pub fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        _ => false,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        _ => crate::value::cmp_value(a, b) == std::cmp::Ordering::Equal,
    }
}

fn to_num(v: &Value) -> EResult<f64> {
    match v {
        Value::Num(n) => Ok(*n),
        Value::Bool(b) => Ok(if *b { 1.0 } else { 0.0 }),
        Value::Str(s) => Ok(s.trim().parse::<f64>().unwrap_or(f64::NAN)),
        _ => Err(AgrError::Other(format!(
            "Cannot convert {} to a number",
            v.display()
        ))),
    }
}

pub fn apply_bin(op: BinOp, l: &Value, r: &Value) -> Value {
    match op {
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div => {
            // date arithmetic
            if let Value::Str(x) = l {
                if is_date_str(x) {
                    if let (Some(a), Some(b)) = (parse_date_str(x), to_num(r).ok()) {
                        let _ = (a, b);
                    }
                }
            }
            let a = to_num(l).unwrap_or(f64::NAN);
            let b = to_num(r).unwrap_or(f64::NAN);
            let v = match op {
                BinOp::Add => a + b,
                BinOp::Sub => a - b,
                BinOp::Mul => a * b,
                _ => a / b,
            };
            Value::Num(v)
        }
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            let o = crate::value::cmp_value(l, r);
            let res = match op {
                BinOp::Lt => o == std::cmp::Ordering::Less,
                BinOp::Le => o != std::cmp::Ordering::Greater,
                BinOp::Gt => o == std::cmp::Ordering::Greater,
                _ => o != std::cmp::Ordering::Less,
            };
            Value::Bool(res)
        }
        _ => Value::Null,
    }
}

fn is_date_str(s: &str) -> bool {
    crate::dates::parse_date(s).is_some()
}

fn parse_date_str(s: &str) -> Option<f64> {
    crate::dates::parse_date(s).map(|d| d)
}

/// call a builtin function
fn call_func(name: &str, args: &[Expr], rec: &Record) -> EResult<Value> {
    let mut vals = Vec::with_capacity(args.len());
    for a in args {
        vals.push(eval(a, rec)?);
    }
    let f = |i: usize| vals.get(i).cloned().unwrap_or(Value::Null);
    match name {
        "abs" => Ok(Value::Num(crate::math1(f(0), |x| x.abs())?)),
        "acos" => Ok(Value::Num(crate::math1(f(0), |x| x.acos())?)),
        "asin" => Ok(Value::Num(crate::math1(f(0), |x| x.asin())?)),
        "atan" => Ok(Value::Num(crate::math1(f(0), |x| x.atan())?)),
        "atan2" => Ok(Value::Num(
            to_num(&f(0))? * 0.0 + crate::math2(&f(0), &f(1), |a, b| a.atan2(b))?,
        )),
        "cbrt" => Ok(Value::Num(crate::math1(f(0), |x| x.cbrt())?)),
        "ceil" => Ok(Value::Num(crate::math1(f(0), |x| x.ceil())?)),
        "cos" => Ok(Value::Num(crate::math1(f(0), |x| x.cos())?)),
        "cosh" => Ok(Value::Num(crate::math1(f(0), |x| x.cosh())?)),
        "exp" => Ok(Value::Num(crate::math1(f(0), |x| x.exp())?)),
        "expm1" => Ok(Value::Num(crate::math1(f(0), |x| x.exp_m1())?)),
        "floor" => Ok(Value::Num(crate::math1(f(0), |x| x.floor())?)),
        "hypot" => Ok(Value::Num(crate::math2(&f(0), &f(1), |a, b| a.hypot(b))?)),
        "log" => Ok(Value::Num(crate::math1(f(0), |x| x.ln())?)),
        "log10" => Ok(Value::Num(crate::math1(f(0), |x| x.log10())?)),
