                let n = a.len() as i64;
                let idx = if *i < 0 { n + *i } else { *i };
                if idx < 0 || idx >= n {
                    return Err(AgrError::IndexOutOfRange(*i));
                }
                Some(a[idx as usize].clone())
            }
            (_, other) => match p {
                PathPart::Key(_) => Err(AgrError::ExpectedObject(other.display())),
                PathPart::Index(_) => Err(AgrError::ExpectedArray(other.display())),
            },
        };
        if cur.is_none() {
            // missing key inside a map -> error
            return Err(AgrError::MissingKey(path_src(parts)));
        }
    }
    Ok(cur)
}

fn path_src(parts: &[PathPart]) -> String {
    let mut s = String::new();
    for (i, p) in parts.iter().enumerate() {
        match p {
            PathPart::Key(k) => {
                if i == 0 {
                    s.push_str(k);
                } else {
                    s.push('.');
                    s.push_str(k);
                }
            }
            PathPart::Index(idx) => {
                s.push_str(&format!("[{}]", idx));
            }
        }
    }
    s
}

pub fn eval(e: &Expr, rec: &Record) -> EResult<Value> {
    match e {
        Expr::Lit(v) => Ok(v.clone()),
        Expr::Path(p) => match resolve_path(rec, &p.parts)? {
            Some(v) => Ok(v),
            None => Ok(Value::Null),
        },
        Expr::Not(e) => Ok(Value::Bool(!truthy(&eval(e, rec)?))),
        Expr::Bin(op, l, r) => {
            match op {
                BinOp::And => {
                    let lv = eval(l, rec)?;
                    if !truthy(&lv) {
                        return Ok(Value::Bool(false));
                    }
                    let rv = eval(r, rec)?;
                    Ok(Value::Bool(truthy(&rv)))
                }
                BinOp::Or => {
                    let lv = eval(l, rec)?;
                    if truthy(&lv) {
                        return Ok(Value::Bool(true));
                    }
                    let rv = eval(r, rec)?;
                    Ok(Value::Bool(truthy(&rv)))
                }
                BinOp::Eq | BinOp::Ne => {
                    let lv = eval(l, rec)?;
                    let rv = eval(r, rec)?;
                    let eq = values_equal(&lv, &rv);
                    Ok(Value::Bool(if *op == BinOp::Eq { eq } else { !eq }))
                }
                _ => {
                    let lv = eval(l, rec)?;
                    let rv = eval(r, rec)?;
                    Ok(apply_bin(*op, &lv, &rv))
                }
            }
        }
        Expr::Func(name, args) => call_func(name, args, rec),
    }
}

pub fn truthy(v: &Value) -> bool {
    match v {
        Value::Bool(b) => *b,
        _ => false,
    }
}

fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Num(x), Value::Num(y)) => x == y,
        (Value::Str(x), Value::Str(y)) => x == y,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        _ => crate::value::cmp_value(a, b) == std::cmp::Ordering::Equal,
    }
}

fn to_num(v: &Value) -> EResult<f64> {
    match v {
        Value::Num(n) => Ok(*n),
        Value::Bool(b) => Ok(if *b { 1.0 } else { 0.0 }),
        Value::Str(s) => Ok(s.trim().parse::<f64>().unwrap_or(f64::NAN)),
        _ => Err(AgrError::Other(format!(
            "Cannot convert {} to a number",
            v.display()
        ))),
    }
}

pub fn apply_bin(op: BinOp, l: &Value, r: &Value) -> Value {
    match op {
        BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div => {
            // date arithmetic
            if let Value::Str(x) = l {
                if is_date_str(x) {
                    if let (Some(a), Some(b)) = (parse_date_str(x), to_num(r).ok()) {
                        let _ = (a, b);
                    }
                }
            }
            let a = to_num(l).unwrap_or(f64::NAN);
            let b = to_num(r).unwrap_or(f64::NAN);
            let v = match op {
                BinOp::Add => a + b,
                BinOp::Sub => a - b,
                BinOp::Mul => a * b,
                _ => a / b,
            };
            Value::Num(v)
        }
        BinOp::Lt | BinOp::Le | BinOp::Gt | BinOp::Ge => {
            let o = crate::value::cmp_value(l, r);
            let res = match op {
                BinOp::Lt => o == std::cmp::Ordering::Less,
                BinOp::Le => o != std::cmp::Ordering::Greater,
                BinOp::Gt => o == std::cmp::Ordering::Greater,
                _ => o != std::cmp::Ordering::Less,
            };
            Value::Bool(res)
        }
        _ => Value::Null,
    }
}

fn is_date_str(s: &str) -> bool {
    crate::dates::parse_date(s).is_some()
}

fn parse_date_str(s: &str) -> Option<f64> {
    crate::dates::parse_date(s).map(|d| d)
}

/// call a builtin function
fn call_func(name: &str, args: &[Expr], rec: &Record) -> EResult<Value> {
    let mut vals = Vec::with_capacity(args.len());
    for a in args {
        vals.push(eval(a, rec)?);
    }
    let f = |i: usize| vals.get(i).cloned().unwrap_or(Value::Null);
    match name {
        "abs" => Ok(Value::Num(crate::math1(f(0), |x| x.abs())?)),
        "acos" => Ok(Value::Num(crate::math1(f(0), |x| x.acos())?)),
        "asin" => Ok(Value::Num(crate::math1(f(0), |x| x.asin())?)),
        "atan" => Ok(Value::Num(crate::math1(f(0), |x| x.atan())?)),
        "atan2" => Ok(Value::Num(
            to_num(&f(0))? * 0.0 + crate::math2(&f(0), &f(1), |a, b| a.atan2(b))?,
        )),
        "cbrt" => Ok(Value::Num(crate::math1(f(0), |x| x.cbrt())?)),
        "ceil" => Ok(Value::Num(crate::math1(f(0), |x| x.ceil())?)),
        "cos" => Ok(Value::Num(crate::math1(f(0), |x| x.cos())?)),
        "cosh" => Ok(Value::Num(crate::math1(f(0), |x| x.cosh())?)),
        "exp" => Ok(Value::Num(crate::math1(f(0), |x| x.exp())?)),
        "expm1" => Ok(Value::Num(crate::math1(f(0), |x| x.exp_m1())?)),
        "floor" => Ok(Value::Num(crate::math1(f(0), |x| x.floor())?)),
        "hypot" => Ok(Value::Num(crate::math2(&f(0), &f(1), |a, b| a.hypot(b))?)),
        "log" => Ok(Value::Num(crate::math1(f(0), |x| x.ln())?)),
        "log10" => Ok(Value::Num(crate::math1(f(0), |x| x.log10())?)),
        "log1p" => Ok(Value::Num(crate::math1(f(0), |x| x.ln_1p())?)),
        "round" => Ok(Value::Num(crate::math1(f(0), |x| x.round())?)),
        "sin" => Ok(Value::Num(crate::math1(f(0), |x| x.sin())?)),
        "sinh" => Ok(Value::Num(crate::math1(f(0), |x| x.sinh())?)),
        "sqrt" => Ok(Value::Num(crate::math1(f(0), |x| x.sqrt())?)),
        "tan" => Ok(Value::Num(crate::math1(f(0), |x| x.tan())?)),
        "tanh" => Ok(Value::Num(crate::math1(f(0), |x| x.tanh())?)),
        "toDegrees" => Ok(Value::Num(crate::math1(f(0), |x| x.to_degrees())?)),
        "toRadians" => Ok(Value::Num(crate::math1(f(0), |x| x.to_radians())?)),
        "concat" => {
            let mut s = String::new();
            for v in &vals {
                s.push_str(&v.display());
            }
            Ok(Value::Str(s))
        }
        "contains" => {
            let h = f(0);
            let n = f(1);
            match (&h, &n) {
                (Value::Str(h), Value::Str(n)) => Ok(Value::Bool(h.contains(n.as_str()))),
                (Value::Arr(a), n) => Ok(Value::Bool(a.iter().any(|x| values_equal(x, n)))),
                _ => Ok(Value::Bool(false)),
            }
        }
        "length" => match f(0) {
            Value::Str(s) => Ok(Value::Num(s.chars().count() as f64)),
            Value::Arr(a) => Ok(Value::Num(a.len() as f64)),
            Value::Map(m) => Ok(Value::Num(m.len() as f64)),
            other => Err(AgrError::Other(format!(
                "length() only works on strings and arrays, found {}",
                other.display()
            ))),
        },
        "now" => Ok(Value::Str(crate::dates::now_string())),
        "num" => match f(0) {
            Value::Num(n) => Ok(Value::Num(n)),
            Value::Str(s) => match s.trim().parse::<f64>() {
                Ok(n) => Ok(Value::Num(n)),
                Err(_) => Ok(Value::Null),
            },
            Value::Bool(b) => Ok(Value::Num(if b { 1.0 } else { 0.0 })),
            Value::Null => Ok(Value::Null),
            other => Err(AgrError::Other(format!(
                "Cannot convert {} to a number",
                other.display()
            ))),
        },
        "parseDate" => match f(0) {
            Value::Str(s) => match crate::dates::parse_date(&s) {
                Some(_) => Ok(Value::Str(crate::dates::format_date(&s))),
                None => Err(AgrError::ParseDate(if s.is_empty() {
                    "NoDate".to_string()
                } else {
                    format!("UnrecognizedToken({:?})", s)
                })),
            },
            other => Err(AgrError::Other(format!(
                "The 'parseDate' function requires a string, found {}",
                other.display()
            ))),
        },
        "parseHex" => match f(0) {
            Value::Str(s) => match i64::from_str_radix(s.trim_start_matches("0x"), 16) {
                Ok(n) => Ok(Value::Num(n as f64)),
                Err(_) => Err(AgrError::ParseHex(format!("invalid hex string -- {}", s))),
            },
            other => Err(AgrError::Other(format!(
                "The 'parseHex' function requires a string, found {}",
                other.display()
            ))),
        },
        "substring" => match f(0) {
            Value::Str(s) => {
                let start = crate::value::fmt_to_int(&f(1));
                let end = if args.len() > 2 {
                    Some(crate::value::fmt_to_int(&f(2)))
                } else {
                    None
                };
                let chars: Vec<char> = s.chars().collect();
                let st = (start as usize).min(chars.len());
                let en = match end {
                    Some(e) => (e as usize).min(chars.len()),
                    None => chars.len(),
                };
                if st > en {
                    return Ok(Value::Str(String::new()));
                }
                Ok(Value::Str(chars[st..en].iter().collect()))
            }
            other => Err(AgrError::Other(format!(
                "substring() requires a string, found {}",
                other.display()
            ))),
        },
        "toLowerCase" => match f(0) {
            Value::Str(s) => Ok(Value::Str(s.to_lowercase())),
            other => Err(AgrError::Other(format!(
                "toLowerCase() requires a string, found {}",
                other.display()
            ))),
        },
        "toUpperCase" => match f(0) {
            Value::Str(s) => Ok(Value::Str(s.to_uppercase())),
            other => Err(AgrError::Other(format!(
                "toUpperCase() requires a string, found {}",
                other.display()
            ))),
        },
        "isNull" => Ok(Value::Bool(matches!(f(0), Value::Null))),
        "isEmpty" => Ok(Value::Bool(match f(0) {
            Value::Null => true,
            Value::Str(s) => s.is_empty(),
            Value::Arr(a) => a.is_empty(),
            Value::Map(m) => m.is_empty(),
            _ => false,
        })),
        "isBlank" => Ok(Value::Bool(match f(0) {
            Value::Null => true,
            Value::Str(s) => s.trim().is_empty(),
            _ => false,
        })),
        "isNumeric" => match f(0) {
            Value::Num(_) => Ok(Value::Bool(true)),
            Value::Str(s) => Ok(Value::Bool(s.trim().parse::<f64>().is_ok())),
            _ => Ok(Value::Bool(false)),
        },
        _ => Err(AgrError::UnknownFunction(name.to_string())),
    }
}
