pub struct AggRow {
    pub keys: Vec<(String, Value)>,
    pub values: Vec<(String, Value)>,
}

#[derive(Clone, Debug)]
pub enum Rows {
    /// records as they come out of the pipeline
    Records(Vec<Record>),
    /// aggregated rows
    Agg(Vec<AggRow>),
}

fn pad_to(s: &str, w: usize) -> String {
    let len = s.len();
    if len >= w {
        s.to_string()
    } else {
        let mut o = s.to_string();
        for _ in 0..(w - len) {
            o.push(' ');
        }
        o
    }
}

// ---------------------------------------------------------------------------
// legacy
// ---------------------------------------------------------------------------
pub struct LegacyRow {
    pub cols: Vec<String>,
    pub widths: Vec<usize>,
    pub order: Vec<String>,
}

pub struct LegacyState {
    pub order: Vec<String>,
    pub widths: Vec<usize>,
}

impl LegacyState {
    pub fn new() -> Self {
        LegacyState {
            order: Vec::new(),
            widths: Vec::new(),
        }
    }

    pub fn render(&mut self, rec: &Record) -> String {
        match rec {
            Record::Raw(s) => s.clone(),
            Record::Fields(m) => {
                // append new columns in sorted order
                let mut newcols: Vec<&String> = m.keys().filter(|k| !self.order.contains(k)).collect();
                newcols.sort();
                for k in newcols {
                    self.order.push(k.clone());
                    self.widths.push(0);
                }
                let mut out = String::new();
                let mut printed_any = false;
                for (idx, name) in self.order.iter().enumerate() {
                    match m.get(name) {
                        Some(v) => {
                            let cell = format!("[{}={}]", name, v.display());
                            let cand = name.len() + 11 + name.len().max(v.display().len());
                            if cand >= self.widths[idx] + 5 {
                                self.widths[idx] = cand;
                            }
                            out.push_str(&cell);
                            out.push_str(&" ".repeat(self.widths[idx].saturating_sub(cell.len())));
                            printed_any = true;
                        }
                        None => {
                            if printed_any {
                                out.push_str(&" ".repeat(self.widths[idx]));
                            }
                        }
                    }
                }
                out.trim_end().to_string()
            }
        }
    }
}

// ---------------------------------------------------------------------------
// aggregate table (legacy)
// ---------------------------------------------------------------------------
pub struct TableState {
    pub widths: Vec<usize>,
}

impl TableState {
    pub fn new() -> Self {
        TableState { widths: Vec::new() }
    }
}

pub fn render_table(headers: &[String], rows: &[Vec<String>]) -> String {
    // widths
    let mut widths: Vec<usize> = Vec::new();
    for h in headers {
        widths.push(h.len() + SEP);
    }
    for (i, r) in rows.iter().enumerate() {
        for (j, c) in r.iter().enumerate() {
            let cand = headers[j].len().max(c.len()) + SEP;
            if cand >= widths[j] + 5 {
                widths[j] = cand;
            }
        }
        let _ = i;
    }
    let mut out = String::new();
    for (i, h) in headers.iter().enumerate() {
        if i + 1 == headers.len() {
            out.push_str(h);
        } else {
            out.push_str(&pad_to(h, widths[i]));
        }
    }
    out.push('\n');
    let total: usize = widths.iter().sum();
    for _ in 0..total {
        out.push('-');
    }
    out.push('\n');
    for r in rows {
        for (i, c) in r.iter().enumerate() {
            if i + 1 == r.len() {
                out.push_str(c);
            } else {
                out.push_str(&pad_to(c, widths[i]));
            }
        }
        out.push('\n');
    }
    out
}

// ---------------------------------------------------------------------------
// json
// ---------------------------------------------------------------------------
pub fn render_json_row(rec: &Record) -> String {
    match rec {
        Record::Raw(_) => "{}".to_string(),
        Record::Fields(m) => {
            let mut s = String::from("{");
            for (i, (k, v)) in m.iter().enumerate() {
                if i > 0 {
                    s.push(',');
                }
                s.push_str(&json_string(k));
                s.push(':');
                s.push_str(&v.to_json());
            }
            s.push('}');
            s
        }
    }
}

pub fn render_json_agg(rows: &[AggRow]) -> String {
    let mut s = String::from("[");
    for (i, r) in rows.iter().enumerate() {
        if i > 0 {
            s.push(',');
        }
        s.push('{');
        let mut first = true;
        for (k, v) in r.keys.iter().chain(r.values.iter()) {
            if !first {
                s.push(',');
            }
            first = false;
            s.push_str(&json_string(k));
            s.push(':');
            s.push_str(&v.to_json());
        }
        s.push('}');
    }
    s.push(']');
    s
}

// ---------------------------------------------------------------------------
// logfmt
// ---------------------------------------------------------------------------
pub fn render_logfmt_row(rec: &Record) -> String {
    match rec {
        Record::Raw(_) => String::new(),
        Record::Fields(m) => {
            let mut parts: Vec<String> = Vec::new();
            for (k, v) in m.iter() {
                parts.push(format!("{}={}", k, v.display()));
            }
            parts.join(" ")
        }
    }
}

pub fn render_logfmt_agg(rows: &[AggRow]) -> String {
    let mut out = String::new();
    for r in rows {
        let mut parts: Vec<String> = Vec::new();
        for (k, v) in r.values.iter().chain(r.keys.iter()) {
            parts.push(format!("{}={}", k, v.display()));
        }
        out.push_str(&parts.join(" "));
        out.push('\n');
    }
    out
}

// ---------------------------------------------------------------------------
// format=<rust fmt string>
// ---------------------------------------------------------------------------
pub fn render_format(rec: &Record, fmt: &FormatStr) -> String {
    let mut out = String::new();
    for piece in &fmt.pieces {
        match piece {
            FmtPiece::Lit(s) => out.push_str(s),
            FmtPiece::Arg { name, spec } => {
                let val = rec.get(name);
                let disp = match val {
                    Some(v) => v.display(),
                    None => "None".to_string(),
                };
                out.push_str(&apply_spec(&disp, spec));
            }
        }
    }
    out
}

#[derive(Clone, Debug)]
pub struct FmtSpec {
    pub align: Option<char>,
    pub width: Option<usize>,
    pub precision: Option<usize>,
}

#[derive(Clone, Debug)]
pub enum FmtPiece {
    Lit(String),
    Arg {
        name: String,
        spec: FmtSpec,
    },
}

#[derive(Clone, Debug)]
pub struct FormatStr {
    pub pieces: Vec<FmtPiece>,
}

pub fn apply_spec(s: &str, spec: &FmtSpec) -> String {
    let mut s = s.to_string();
    if let Some(p) = spec.precision {
        s = s.chars().take(p).collect();
    }
    let w = spec.width.unwrap_or(0);
    if s.len() >= w {
        return s;
    }
    let pad = w - s.len();
    match spec.align {
        Some('<') | None => s + &" ".repeat(pad),
        Some('>') => " ".repeat(pad) + &s,
        Some('^') => {
            let l = pad / 2;
            let r = pad - l;
            " ".repeat(l) + &s + &" ".repeat(r)
        }
        _ => s,
    }
}
