//! format string parser (python-style specs, rust-style messages)

use crate::render::{FmtPiece, FmtSpec, FormatStr};

pub struct FErr(pub String);

fn num_parse(s: &str) -> Option<usize> {
    if s.is_empty() {
        return None;
    }
    s.parse::<usize>().ok()
}

const NUM_CODES: &[char] = &['b', 'o', 'x', 'X', 'f', 'F', 'e', 'E', '%'];

pub fn parse_format(s: &str) -> Result<FormatStr, FErr> {
    let ch: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    let mut pieces: Vec<FmtPiece> = Vec::new();
    let mut lit = String::new();
    while i < ch.len() {
        let c = ch[i];
        if c == '{' {
            if i + 1 < ch.len() && ch[i + 1] == '{' {
                lit.push('{');
                i += 2;
                continue;
            }
            // flush literal
            if !lit.is_empty() {
                pieces.push(FmtPiece::Lit(std::mem::take(&mut lit)));
            }
            // find the end
            let start = i;
            i += 1;
            let mut name = String::new();
            let mut spec = String::new();
            let mut in_spec = false;
            let mut closed = false;
            while i < ch.len() {
                let c = ch[i];
                if c == '}' {
                    closed = true;
                    i += 1;
                    break;
                }
                if c == ':' && !in_spec {
                    in_spec = true;
                    i += 1;
                    continue;
                }
                if in_spec {
                    spec.push(c);
                } else {
                    name.push(c);
                }
                i += 1;
            }
            if !closed {
                return Err(FErr("Invalid(Expected '}' before end of string)".into()));
            }
            if name.is_empty() {
                return Err(FErr("Invalid(must specify identifier)".into()));
            }
            let spec_parsed = parse_spec(&spec)?;
            pieces.push(FmtPiece::Arg {
                name,
                spec: spec_parsed,
            });
            let _ = start;
            continue;
        }
        if c == '}' {
            if i + 1 < ch.len() && ch[i + 1] == '}' {
                lit.push('}');
                i += 2;
                continue;
            }
            return Err(FErr("Invalid(Single '}' encountered in format string)".into()));
        }
        lit.push(c);
        i += 1;
    }
    if !lit.is_empty() {
        pieces.push(FmtPiece::Lit(lit));
    }
    Ok(FormatStr { pieces })
}

fn parse_spec(spec: &str) -> Result<FmtSpec, FErr> {
    if spec.is_empty() {
        return Ok(FmtSpec {
            align: None,
            width: None,
            precision: None,
        });
    }
    let ch: Vec<char> = spec.chars().collect();
    let mut i = 0usize;
    let mut align = None;
    // fill + align
    if ch.len() >= 2 {
        let c0 = ch[0];
        let c1 = ch[1];
        if c1 == '<' || c1 == '>' || c1 == '^' {
            align = Some(c1);
            i = 2;
        } else if c1 == '=' {
            return Err(FErr(
                "Invalid(sign aware zero padding and Align '=' not yet supported)".into(),
            ));
        } else if c0 == '<' || c0 == '>' || c0 == '^' {
            align = Some(c0);
            i = 1;
        } else if c0 == '=' {
            return Err(FErr(
                "Invalid(sign aware zero padding and Align '=' not yet supported)".into(),
            ));
        }
    } else if !ch.is_empty() && (ch[0] == '<' || ch[0] == '>' || ch[0] == '^') {
        align = Some(ch[0]);
        i = 1;
    }
    // sign
    if i < ch.len() && (ch[i] == '+' || ch[i] == '-' || ch[i] == ' ') {
        return Err(FErr(
            "TypeError(Sign not allowed in string format specifier)".into(),
        ));
    }
    // alternate form
    if i < ch.len() && ch[i] == '#' {
        return Err(FErr(
            "TypeError(Alternate form (#) not allowed in string format specifier)".into(),
        ));
    }
    // zero padding
    if i + 1 < ch.len() && ch[i] == '0' && (ch[i + 1].is_ascii_digit() || ch[i + 1] == '=') {
        return Err(FErr(
            "Invalid(sign aware zero padding and Align '=' not yet supported)".into(),
        ));
    }
    // width
    let ws = i;
    while i < ch.len() && ch[i].is_ascii_digit() {
        i += 1;
    }
    let width = num_parse(&ch[ws..i].iter().collect::<String>());
    // comma
    if i < ch.len() && ch[i] == ',' {
        return Err(FErr("TypeError(Cannot specify ',' with 's')".into()));
    }
    // precision
    let mut precision = None;
    if i < ch.len() && ch[i] == '.' {
        i += 1;
        let ps = i;
        while i < ch.len() && ch[i].is_ascii_digit() {
            i += 1;
        }
        if i == ps {
            return Err(FErr("Invalid(Format specifier missing precision)".into()));
        }
        precision = Some(ch[ps..i].iter().collect::<String>().parse::<usize>().unwrap_or(0));
    }
    // type
    if i < ch.len() {
        let t = ch[i];
        if t == 's' {
            // ok
        } else if NUM_CODES.contains(&t) {
            return Err(FErr(format!(
                "TypeError(Unknown format code Some('{}') for object of type 'str')",
                t
            )));
        } else {
            return Err(FErr(format!("TypeError(Invalid type specifier: '{}')", t)));
        }
        i += 1;
        if i < ch.len() {
            return Err(FErr("Invalid(Invalid format specifier)".into()));
        }
    }
    Ok(FmtSpec {
        align,
        width,
        precision,
    })
}
RSEOF
