pub fn format_date(s: &str) -> String {
    match parse_date_parts(s) {
        Some(secs) => {
            let (y, mo, d, h, mi, sec) = epoch_to_civil(secs);
            let frac = s
                .find(|c: char| c == '.' && c.is_ascii_punctuation())
