            .duration_since(std::time::UNIX_EPOCH)
            .ok()?
            .as_secs() as i64;
        let (y, mo, d, _, _, _) = epoch_to_civil(now);
        return build(Parsed {
            y,
            mo,
            d,
            h: p.0,
            mi: p.1,
            s: p.2,
        })
        .ok();
    }
    // numeric-only: YYYYMMDD
    if !body.is_empty() && body.chars().all(|c| c.is_ascii_digit()) {
        match body.len() {
            8 => {
                let y: i64 = body[0..4].parse().ok()?;
                let mo: i64 = body[4..6].parse().ok()?;
                let d: i64 = body[6..8].parse().ok()?;
                return build(Parsed { y, mo, d, h: 0, mi: 0, s: 0 }).ok();
            }
            4 | 9 | 10 => return None,
            _ => return None,
        }
    }
    // ISO-ish: y-m-d[T| ]hh:mm[:ss[.frac]][ tz]
    let (dpart, tpart) = split_dt(body);
    let (y, mo, d) = parse_date_component(dpart)?;
    let (h, mi, sec) = if tpart.is_empty() {
        (0, 0, 0)
    } else {
        parse_time(tpart)?
    };
    build(Parsed { y, mo, d, h, mi, s: sec }).ok()
