fn split_tz(s: &str) -> (&str, &str) {
    let t = s.trim_end();
    for pat in [" UTC", "Z", "+0000", "-0000"] {
        if let Some(i) = t.rfind(pat) {
            if pat == "Z" && i + 1 == t.len() {
                return (&t[..i], "");
            }
            if pat != "Z" {
                let rest = &t[i + pat.len()..];
                if rest.trim().is_empty() || !rest.starts_with(|c: char| c.is_ascii_digit()) {
                    return (&t[..i], rest);
                }
            }
        }
    }
    // +HH:MM / -HH:MM / +HHMM at the end
    let b: Vec<char> = t.chars().collect();
    if b.len() > 5 {
        let l = b[b.len() - 1];
        let c = b[b.len() - 3];
        let sign = b[b.len() - 6];
        if (sign == '+' || sign == '-') && c == ':' && l.is_ascii_digit() {
            return (t[..t.len() - 6].trim_end(), "");
        }
        if (sign == '+' || sign == '-') && l.is_ascii_digit() && b[b.len() - 5].is_ascii_digit() && b[b.len()-4].is_ascii_digit() && b[b.len()-3].is_ascii_digit() && b[b.len()-2].is_ascii_digit() {
            return (t[..t.len() - 5].trim_end(), "");
        }
    }
    (t, "")
}

fn split_dt(s: &str) -> (&str, &str) {
    let t = s.trim();
    if let Some(i) = t.find('T') {
        (&t[..i], t[i + 1..].trim())
    } else {
        // find a space that separates a date from a time
        let parts: Vec<&str> = t.splitn(2, ' ').collect();
        if parts.len() == 2 && looks_like_time(parts[1]) {
            (parts[0], parts[1])
        } else {
            (t, "")
        }
    }
}

fn looks_like_time(s: &str) -> bool {
    let t = s.trim();
    let c: Vec<char> = t.chars().collect();
    if c.len() < 4 {
        return false;
    }
    c[0].is_ascii_digit() && c[1].is_ascii_digit() && c[2] == ':' && c[3].is_ascii_digit()
}

fn parse_date_component(s: &str) -> Result<(i64, i64, i64), ()> {
    let t = s.trim().trim_matches(|c: char| c == ',' || c == ' ');
    // YYYY-MM-DD / YYYY/MM/DD / YYYY MM DD
    let seps: Vec<char> = t.chars().filter(|c| !c.is_ascii_alphanumeric()).collect();
    if seps.is_empty() {
        // compact
        if t.len() == 8 {
            return Ok((
                t[0..4].parse().map_err(|_| ())?,
                t[4..6].parse().map_err(|_| ())?,
                t[6..8].parse().map_err(|_| ())?,
            ));
        }
        return Err(());
    }
    let sep = seps[0];
    let parts: Vec<&str> = t.split(sep).collect();
    if parts.len() == 3 {
        let a: i64 = parts[0].trim().parse().map_err(|_| ())?;
        let b: i64 = parts[1].trim().parse().map_err(|_| ())?;
        let c: i64 = parts[2].trim().parse().map_err(|_| ())?;
        if a > 31 {
            return Ok((a, b, c));
        }
        return Ok((c, a, b));
    }
    Err(())
}

fn parse_time(s: &str) -> Result<(i64, i64, i64), ()> {
    let t = s.trim();
    let t = t.trim_end_matches(|c: char| c.is_ascii_alphabetic() || c == '+' || c == '-');
    let t = t.trim();
    let t = if let Some(i) = t.rfind(|c: char| c == '+' || c == '-') {
        if i > 8 {
            t[..i].trim_end()
        } else {
            t
        }
    } else {
        t
    };
    let main = t.split('.').next().unwrap_or(t);
    let parts: Vec<&str> = main.split(':').collect();
    if parts.len() < 2 {
        return Err(());
    }
    let h: i64 = parts[0].trim().parse().map_err(|_| ())?;
    let mi: i64 = parts[1].trim().parse().map_err(|_| ())?;
    let sec: i64 = if parts.len() > 2 {
        parts[2].trim().parse().map_err(|_| ())?
    } else {
        0
    };
    Ok((h, mi, sec))
}
