//! pipeline evaluation

use crate::format::{apply_spec, parse_format, FormatStr};
use crate::opsparse::unquote;
use crate::query::*;
use crate::record::Record;
use crate::render::*;
use crate::value::*;

pub struct Out {
    /// stderr "error: ..." lines emitted while running
    pub errors: Vec<String>,
}

fn rep_err(out: &mut Out, e: &crate::eval::AgrError) {
    out.errors.push(format!("{}", e));
}

// ---------------------------------------------------------------------------
// filters
// ---------------------------------------------------------------------------
fn line_matches(rec: &Record, f: &Filter) -> bool {
    let hay = match rec {
        Record::Raw(s) => s.clone(),
        Record::Fields(m) => {
            let mut parts = Vec::new();
            for (k, v) in m.iter() {
                parts.push(k.clone());
                parts.push(v.display());
            }
            parts.join(" ")
        }
    };
    match_filter(&hay, f)
}

fn match_filter(hay: &str, f: &Filter) -> bool {
    match f {
        Filter::Match { pat, insensitive } => {
            if *insensitive {
                let h = hay.to_lowercase();
                let p = pat.to_lowercase();
                h.contains(&p)
            } else {
                hay.contains(pat.as_str())
            }
        }
        Filter::And(items) => items.iter().all(|f| match_filter(hay, f)),
        Filter::Or(items) => items.iter().any(|f| match_filter(hay, f)),
        Filter::Not(inner) => !match_filter(hay, inner),
    }
}

// ---------------------------------------------------------------------------
// aggregation
// ---------------------------------------------------------------------------
#[derive(Clone, Debug)]
pub struct GroupState {
    pub count: u64,
    pub values: Vec<Value>,
}

struct Aggregator {
    name: String,
    kind: AggKind,
}

#[derive(Clone, Copy, PartialEq)]
enum AggKind {
    Count,
    Sum,
    Min,
    Max,
    Average,
    CountDistinct,
    Percentile(u32),
}

pub struct Pipeline {
    pub ops: Vec<Op>,
    /// which operator index starts the aggregate stage
    pub agg_index: Option<usize>,
}

fn op_is_agg(op: &Op) -> bool {
    matches!(
        op,
        Op::Count { .. }
            | Op::Sum(..)
            | Op::Min(..)
            | Op::Max(..)
            | Op::Average(..)
            | Op::CountDistinct(..)
            | Op::Percentile(..)
            | Op::Sort(..)
    )
}

/// Applies one aggregate stage given the list of aggregate ops and the by keys.
/// Returns (header names, rows) with rows sorted per the tool's default order.
pub fn run_aggregate(
    rows: &[Record],
    ops: &[Op],
    by: &[Expr],
    out: &mut Out,
) -> Vec<AggRow> {
    // build aggregator list
    let mut aggs: Vec<Aggregator> = Vec::new();
    for op in ops {
        match op {
            Op::Count { cond, name, .. } => aggs.push(Aggregator {
                name: name.clone().unwrap_or_else(|| "_count".to_string()),
                kind: AggKind::Count,
            }),
            Op::Sum(e, name, _) => aggs.push(Aggregator {
                name: name.clone().unwrap_or_else(|| "_sum".to_string()),
                kind: AggKind::Sum,
            }),
            Op::Min(e, name, _) => aggs.push(Aggregator {
                name: name.clone().unwrap_or_else(|| "_min".to_string()),
                kind: AggKind::Min,
            }),
            Op::Max(e, name, _) => aggs.push(Aggregator {
                name: name.clone().unwrap_or_else(|| "_max".to_string()),
                kind: AggKind::Max,
            }),
            Op::Average(e, name, _) => aggs.push(Aggregator {
                name: name.clone().unwrap_or_else(|| "_average".to_string()),
                kind: AggKind::Average,
            }),
            Op::CountDistinct(e, _) => aggs.push(Aggregator {
                name: "_countDistinct".to_string(),
                kind: AggKind::CountDistinct,
            }),
            Op::Percentile(p, e, _) => aggs.push(Aggregator {
                name: format!("p{}", p),
                kind: AggKind::Percentile(*p),
            }),
            _ => {}
        }
    }
    let mut groups: Vec<(Vec<Value>, GroupState)> = Vec::new();
    for rec in rows {
        let mut key = Vec::new();
        for e in by {
            let v = match crate::eval::eval(e, rec) {
                Ok(v) => v,
                Err(_) => Value::Null,
            };
            key.push(v);
        }
        // find or create
        let idx = groups
            .iter()
            .position(|(k, _)| {
                k.len() == key.len()
                    && k.iter()
                        .zip(key.iter())
                        .all(|(a, b)| crate::value::cmp_value(a, b) == std::cmp::Ordering::Equal)
            });
        let idx = match idx {
            Some(i) => i,
            None => {
                groups.push((
                    key.clone(),
                    GroupState {
                        count: 0,
                        values: vec![Value::Null; aggs.len()],
                    },
                ));
                groups.len() - 1
            }
        };
        groups[idx].1.count += 1;
        for (i, op) in ops.iter().enumerate() {
            match op {
                Op::Count { cond, .. } => {
                    if let Some(c) = cond {
                        if let Ok(v) = crate::eval::eval(c, rec) {
                            if crate::eval::truthy(&v) {
                                groups[idx].1.values[i] = Value::Num(
                                    crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64 + 1.0,
                                );
                            }
                        }
                    } else {
                        groups[idx].1.values[i] = Value::Num(
                            crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64 + 1.0,
                        );
                    }
                }
                Op::Sum(e, _, _) | Op::Average(e, _, _) | Op::Min(e, _, _) | Op::Max(e, _, _)
                | Op::Percentile(_, e, _) => {
                    if let Ok(v) = crate::eval::eval(e, rec) {
                        match v {
                            Value::Num(n) => {
                                match aggs[i].kind {
                                    AggKind::Sum => {
                                        let cur = crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64;
                                        groups[idx].1.values[i] = Value::Num(cur + n);
                                    }
                                    AggKind::Average => {
                                        // accumulate as string to preserve precision via re-parsing
                                        let cur = crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64;
                                        groups[idx].1.values[i] = Value::Num(cur + n);
                                    }
                                    AggKind::Min => {
                                        let cur = crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64;
                                        if groups[idx].1.values[i] == Value::Null {
                                            groups[idx].1.values[i] = Value::Num(n);
                                        } else if n < cur {
                                            groups[idx].1.values[i] = Value::Num(n);
                                        }
                                    }
                                    AggKind::Max => {
                                        let cur = crate::value::fmt_to_int(&groups[idx].1.values[i]) as f64;
                                        if groups[idx].1.values[i] == Value::Null {
                                            groups[idx].1.values[i] = Value::Num(n);
                                        } else if n > cur {
                                            groups[idx].1.values[i] = Value::Num(n);
                                        }
                                    }
