use std::collections::HashMap;
use std::sync::Mutex;

static CACHE: Mutex<Option<HashMap<String, regex::Regex>>> = Mutex::new(None);

pub fn get(pat: &str) -> regex::Regex {
    let mut g = CACHE.lock().unwrap();
    let m = g.get_or_insert_with(HashMap::new);
    if let Some(r) = m.get(pat) {
        return r.clone();
    }
    let r = regex::Regex::new(pat).unwrap_or_else(|_| regex::Regex::new("").unwrap());
    m.insert(pat.to_string(), r.clone());
    r
}
