//! pipeline evaluation

use crate::opsparse::unquote;
use crate::query::*;
use crate::record::Record;
use crate::render::*;
use crate::value::*;

pub struct Out {
    pub errors: Vec<String>,
}

fn rep_err(out: &mut Out, e: &crate::eval::AgrError) {
    out.errors.push(format!("{}", e));
}

// ---------------------------------------------------------------------------
// filters
// ---------------------------------------------------------------------------
fn record_text(rec: &Record) -> String {
    match rec {
        Record::Raw(s) => s.clone(),
        Record::Fields(m) => {
            let mut parts = Vec::new();
            for (k, v) in m.iter() {
                parts.push(k.clone());
                parts.push(v.display());
            }
            parts.join(" ")
        }
    }
}

fn match_filter(hay: &str, f: &Filter) -> bool {
    match f {
        Filter::Match { pat, insensitive } => {
            if *insensitive {
                hay.to_lowercase().contains(&pat.to_lowercase())
            } else {
                hay.contains(pat.as_str())
            }
        }
        Filter::And(items) => items.iter().all(|f| match_filter(hay, f)),
        Filter::Or(items) => items.iter().any(|f| match_filter(hay, f)),
        Filter::Not(inner) => !match_filter(hay, inner),
    }
}

// ---------------------------------------------------------------------------
// aggregation
// ---------------------------------------------------------------------------
#[derive(Clone, Copy, PartialEq, Debug)]
enum AggKind {
    Count,
    Sum,
    Min,
    Max,
    Average,
    CountDistinct,
    Percentile(u32),
}

struct AggSpec {
    name: String,
    kind: AggKind,
    cond: Option<Expr>,
    expr: Option<Expr>,
}

struct Acc {
    count: u64,
    sum: f64,
    min: Option<f64>,
    max: Option<f64>,
    seen: Vec<Value>,
    vals: Vec<f64>,
}

impl Acc {
    fn new() -> Self {
        Acc {
            count: 0,
            sum: 0.0,
            min: None,
            max: None,
            seen: Vec::new(),
            vals: Vec::new(),
        }
    }
}

pub struct AggRow {
    pub keys: Vec<(String, Value)>,
    pub values: Vec<(String, Value)>,
}

/// run one aggregate stage
pub fn run_aggregate(rows: &[Record], specs: &[AggSpec], by: &[Expr]) -> Vec<AggRow> {
    let mut groups: Vec<(Vec<Value>, Vec<Acc>)> = Vec::new();
    for rec in rows {
        let mut key = Vec::new();
        for e in by {
            let v = match crate::eval::eval(e, rec) {
                Ok(v) => v,
                Err(_) => Value::Null,
            };
            key.push(v);
        }
        let idx = groups.iter().position(|(k, _)| {
            k.len() == key.len()
                && k.iter()
                    .zip(key.iter())
                    .all(|(a, b)| crate::value::cmp_value(a, b) == std::cmp::Ordering::Equal)
        });
        let idx = match idx {
            Some(i) => i,
            None => {
                groups.push((key.clone(), (0..specs.len()).map(|_| Acc::new()).collect()));
                groups.len() - 1
            }
        };
        let accs = &mut groups[idx].1;
        for (i, s) in specs.iter().enumerate() {
            match s.kind {
                AggKind::Count => {
                    let ok = match &s.cond {
                        Some(c) => match crate::eval::eval(c, rec) {
                            Ok(v) => crate::eval::truthy(&v),
                            Err(_) => false,
                        },
                        None => true,
                    };
                    if ok {
                        accs[i].count += 1;
                    }
                }
                AggKind::CountDistinct => {
                    if let Some(e) = &s.expr {
                        if let Ok(v) = crate::eval::eval(e, rec) {
                            if !accs[i].seen.iter().any(|x| {
                                crate::value::cmp_value(x, &v) == std::cmp::Ordering::Equal
                            }) {
                                accs[i].seen.push(v);
                            }
                        }
                    }
                }
                AggKind::Percentile(_) => {
                    if let Some(e) = &s.expr {
                        if let Ok(v) = crate::eval::eval(e, rec) {
                            if let Value::Num(n) = v {
                                accs[i].vals.push(n);
                            }
                        }
                    }
                }
                AggKind::Sum | AggKind::Average => {
                    if let Some(e) = &s.expr {
                        if let Ok(v) = crate::eval::eval(e, rec) {
                            if let Value::Num(n) = v {
                                accs[i].sum += n;
                                accs[i].count += 1;
                            }
                        }
                    }
                }
                AggKind::Min => {
                    if let Some(e) = &s.expr {
                        if let Ok(v) = crate::eval::eval(e, rec) {
                            if let Value::Num(n) = v {
                                accs[i].min = Some(match accs[i].min {
                                    Some(m) => m.min(n),
                                    None => n,
                                });
                            }
                        }
                    }
                }
                AggKind::Max => {
                    if let Some(e) = &s.expr {
                        if let Ok(v) = crate::eval::eval(e, rec) {
                            if let Value::Num(n) = v {
                                accs[i].max = Some(match accs[i].max {
                                    Some(m) => m.max(n),
                                    None => n,
                                });
                            }
                        }
                    }
                }
            }
        }
    }
    let mut out_rows: Vec<AggRow> = Vec::new();
    for (key, accs) in groups.iter() {
        let mut vals: Vec<(String, Value)> = Vec::new();
        for (i, s) in specs.iter().enumerate() {
            let a = &accs[i];
            let v = match s.kind {
                AggKind::Count => Value::Num(a.count as f64),
                AggKind::Sum => Value::Num(a.sum),
                AggKind::Average => Value::Num(a.sum / a.count as f64),
                AggKind::Min => match a.min {
                    Some(m) => Value::Num(m),
                    None => Value::Null,
                },
                AggKind::Max => match a.max {
                    Some(m) => Value::Num(m),
                    None => Value::Null,
                },
                AggKind::CountDistinct => Value::Num(a.seen.len() as f64),
                AggKind::Percentile(p) => {
                    let mut v = a.vals.clone();
                    v.sort_by(|x, y| x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal));
                    if v.is_empty() {
                        Value::Null
                    } else {
                        let idx = crate::value::pct_index(p as f64 / 100.0, v.len());
                        Value::Num(v[idx])
                    }
                }
            };
            vals.push((s.name.clone(), v));
        }
        let mut keys: Vec<(String, Value)> = Vec::new();
        for (i, e) in by.iter().enumerate() {
            keys.push((e.src(), key[i].clone()));
        }
        out_rows.push(AggRow { keys, values: vals });
    }
    out_rows.sort_by(|a, b| {
        for i in 0..a.values.len().min(b.values.len()) {
            let o = crate::value::cmp_value(&b.values[i].1, &a.values[i].1);
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        for i in 0..a.keys.len().min(b.keys.len()) {
            let o = crate::value::cmp_value(&a.keys[i].1, &b.keys[i].1);
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        std::cmp::Ordering::Equal
    });
    out_rows
}

