fn alias_expand(name: &str) -> Option<Vec<Op>> {
    match name {
        "apache" => Some(vec![Op::Parse {
            mode: ParseMode::Plain,
            pattern: "\\\"* - * [*] \\\"* * *\\\" * *\"".to_string(),
            from: None,
            names: vec![
                "ip".to_string(),
                "name".to_string(),
                "timestamp".to_string(),
                "method".to_string(),
                "url".to_string(),
                "protocol".to_string(),
                "status".to_string(),
                "contentlength".to_string(),
            ],
            nodrop: false,
            noconvert: false,
        }]),
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// main pipeline runner
// ---------------------------------------------------------------------------
pub struct RenderState {
    pub legacy: LegacyState,
    pub out: String,
}

pub fn run_pipeline(
    q: &Query,
    lines: Vec<String>,
    out: &mut Out,
    mode: &OutputMode,
    fmtstr: Option<&FormatStr>,
) -> String {
    // determine whether we have an aggregate stage
    let agg_start = q.ops.iter().position(op_is_agg);
    let mut records: Vec<Record> = Vec::new();
    for line in lines {
        let mut rec = Record::Raw(line.clone());
        if let Some(f) = &q.filters {
            if !match_filter(&record_text(&rec), f) {
                continue;
            }
        }
        records.push(rec);
    }
    // apply non aggregate operators until the aggregate stage
    let mut cur: Vec<Record> = Vec::new();
    let mut pending_print: Vec<Record> = Vec::new();
    for (i, rec) in records.into_iter().enumerate() {
        let _ = i;
        let mut r = rec;
        let mut ok = true;
        for op in q.ops.iter() {
            if op_is_agg(op) {
                cur.push(r);
                ok = false;
                break;
            }
            match apply_op(op, r, out, mode, fmtstr, &mut pending_print) {
                OpOut::Keep(nr) => r = nr,
                OpOut::Drop => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            cur.push(r);
        }
    }
    let _ = pending_print;
    if agg_start.is_none() {
        // non aggregate: print rows as they were produced
        let mut s = String::new();
        let mut st = LegacyState::new();
        for rec in cur.iter() {
            match mode {
                OutputMode::Legacy => {
                    let l = st.render(rec);
                    s.push_str(&l);
                    s.push('\n');
                }
                OutputMode::Json => {
                    s.push_str(&render_json_row(rec));
                    s.push('\n');
                }
                OutputMode::Logfmt => {
                    s.push_str(&render_logfmt_row(rec));
                    s.push('\n');
                }
                OutputMode::Format(_) => {
                    s.push_str(&crate::render::render_format(rec, fmtstr.unwrap()));
                    s.push('\n');
                }
            }
        }
        return s;
    }
    // aggregate: gather aggregate ops + by keys
    let mut specs: Vec<AggSpec> = Vec::new();
    let mut by: Vec<Expr> = Vec::new();
    for op in q.ops.iter() {
        match op {
            Op::Count { cond, name, by: b } => {
                specs.push(AggSpec {
                    name: name.clone().unwrap_or_else(|| "_count".to_string()),
                    kind: AggKind::Count,
                    cond: cond.clone(),
                    expr: None,
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Sum(e, name, b) => {
                specs.push(AggSpec {
                    name: name.clone().unwrap_or_else(|| "_sum".to_string()),
                    kind: AggKind::Sum,
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Min(e, name, b) => {
                specs.push(AggSpec {
                    name: name.clone().unwrap_or_else(|| "_min".to_string()),
                    kind: AggKind::Min,
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Max(e, name, b) => {
                specs.push(AggSpec {
                    name: name.clone().unwrap_or_else(|| "_max".to_string()),
                    kind: AggKind::Max,
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Average(e, name, b) => {
                specs.push(AggSpec {
                    name: name.clone().unwrap_or_else(|| "_average".to_string()),
                    kind: AggKind::Average,
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::CountDistinct(e, b) => {
                specs.push(AggSpec {
                    name: "_countDistinct".to_string(),
                    kind: AggKind::CountDistinct,
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Percentile(p, e, b) => {
                specs.push(AggSpec {
                    name: format!("p{}", p),
                    kind: AggKind::Percentile(*p),
                    cond: None,
                    expr: Some(e.clone()),
                });
                if !b.is_empty() {
                    by = b.clone();
                }
            }
            Op::Sort(keys, dir) => {
                // sorting operator: no aggregation, just sorts the records
                let mut rows = cur.clone();
                sort_records(&mut rows, keys, *dir);
                return render_rows(&rows, mode, fmtstr);
            }
            _ => {}
        }
    }
    if specs.is_empty() {
        return render_rows(&cur, mode, fmtstr);
    }
    let rows = run_aggregate(&cur, &specs, &by);
    if rows.is_empty() {
        return "No data\n".to_string();
    }
    // apply post aggregate non aggregate operators
    let mut final_rows: Vec<Record> = Vec::new();
    for ar in rows.iter() {
        let mut rec = Record::Fields(ar.keys.iter().chain(ar.values.iter()).map(|(k, v)| (k.clone(), v.clone())).collect());
        // legacy table needs the original ordering: keys first then values
        let mut ok = true;
        for op in q.ops.iter().skip(agg_start.unwrap() + 1) {
            if op_is_agg(op) {
                break;
            }
            match apply_op(op, rec, out, mode, fmtstr, &mut Vec::new()) {
                OpOut::Keep(nr) => rec = nr,
                OpOut::Drop => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            final_rows.push(rec);
        }
    }
    // aggregate rendering
    match mode {
        OutputMode::Json => {
            let mut s = String::from("[");
            for (i, ar) in rows.iter().enumerate() {
                if i > 0 {
                    s.push(',');
                }
                s.push('{');
                let mut first = true;
                for (k, v) in ar.keys.iter().chain(ar.values.iter()) {
                    if !first {
                        s.push(',');
                    }
                    first = false;
                    s.push_str(&crate::value::json_string(k));
                    s.push(':');
                    s.push_str(&v.to_json());
                }
                s.push('}');
            }
            s.push(']');
            s.push('\n');
            s
        }
        OutputMode::Logfmt => crate::render::render_logfmt_agg(rows),
        OutputMode::Format(_) => {
            let mut s = String::new();
            for ar in rows.iter() {
                let rec = Record::Fields(
                    ar.keys
                        .iter()
                        .chain(ar.values.iter())
                        .map(|(k, v)| (k.clone(), v.clone()))
                        .collect(),
                );
                s.push_str(&crate::render::render_format(&rec, fmtstr.unwrap()));
                s.push('\n');
            }
            s
        }
        OutputMode::Legacy => {
            // headers: keys then values, in the order used by the rows
            let mut headers: Vec<String> = Vec::new();
            for ar in rows.iter() {
                for (k, _) in ar.keys.iter().chain(ar.values.iter()) {
                    if !headers.contains(k) {
                        headers.push(k.clone());
                    }
                }
            }
            let mut body: Vec<Vec<String>> = Vec::new();
            for ar in rows.iter() {
                let mut row = Vec::new();
                for h in headers.iter() {
                    let v = ar
                        .keys
                        .iter()
                        .chain(ar.values.iter())
                        .find(|(k, _)| k == h)
                        .map(|(_, v)| v.clone())
                        .unwrap_or(Value::Null);
                    row.push(v.display());
                }
                body.push(row);
            }
            crate::render::render_table(&headers, &body)
        }
    }
}

fn render_rows(rows: &[Record], mode: &OutputMode, fmtstr: Option<&FormatStr>) -> String {
    let mut s = String::new();
    let mut st = LegacyState::new();
    for rec in rows.iter() {
        match mode {
            OutputMode::Legacy => {
                let l = st.render(rec);
                s.push_str(&l);
                s.push('\n');
            }
            OutputMode::Json => {
                s.push_str(&render_json_row(rec));
                s.push('\n');
            }
            OutputMode::Logfmt => {
                s.push_str(&render_logfmt_row(rec));
                s.push('\n');
            }
            OutputMode::Format(_) => {
                s.push_str(&crate::render::render_format(rec, fmtstr.unwrap()));
                s.push('\n');
            }
        }
    }
    s
}

fn sort_records(rows: &mut [Record], keys: &[Expr], dir: SortDir) {
    rows.sort_by(|a, b| {
        for e in keys.iter() {
            let va = crate::eval::eval(e, a).unwrap_or(Value::Null);
            let vb = crate::eval::eval(e, b).unwrap_or(Value::Null);
            let o = match dir {
                SortDir::Asc => crate::value::cmp_value(&va, &vb),
                SortDir::Desc => crate::value::cmp_value(&vb, &va),
            };
            if o != std::cmp::Ordering::Equal {
                return o;
            }
        }
        std::cmp::Ordering::Equal
    });
}

pub enum OpOut {
    Keep(Record),
    Drop,
}

pub fn apply_op(
    op: &Op,
    rec: Record,
    out: &mut Out,
    _mode: &OutputMode,
    _fmt: Option<&FormatStr>,
    _pending: &mut Vec<Record>,
) -> OpOut {
    match op {
        Op::Json { from } => {
            let src = match from {
                Some(f) => match rec.get(f) {
                    Some(v) => match v {
                        Value::Str(s) => s,
                        other => {
                            rep_err(
                                out,
                                &crate::eval::AgrError::Other(format!(
                                    "Expected a string, found {}",
                                    other.display()
                                )),
                            );
                            return OpOut::Drop;
                        }
                    },
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!("No value for key \"{}\"", f)),
                        );
                        return OpOut::Drop;
                    }
                },
                None => match rec.raw() {
                    Some(s) => s.clone(),
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other("Expected JSON, found None".to_string()),
                        );
                        return OpOut::Drop;
                    }
                },
            };
            match crate::value::serde_json_like::parse(&src) {
                Ok(v) => {
                    let val = Value::from_json(&v);
                    let mut newrec = Record::Fields(std::collections::BTreeMap::new());
                    if let Value::Map(m) = val {
                        for (k, v) in m {
                            newrec.set(k, v);
                        }
                    } else {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!(
                                "Expected JSON, found {}",
                                src
                            )),
                        );
                        return OpOut::Drop;
                    }
                    OpOut::Keep(newrec)
                }
                Err(_) => {
                    rep_err(
                        out,
                        &crate::eval::AgrError::Other(format!("Expected JSON, found {}", src)),
                    );
                    OpOut::Drop
                }
            }
        }
        Op::Logfmt { from } => {
            let src = match from {
                Some(f) => match rec.get(f) {
                    Some(Value::Str(s)) => s,
                    Some(other) => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!(
                                "Expected a string, found {}",
                                other.display()
                            )),
                        );
                        return OpOut::Drop;
                    }
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!("No value for key \"{}\"", f)),
                        );
                        return OpOut::Drop;
                    }
                },
                None => match rec.raw() {
                    Some(s) => s.clone(),
                    None => {
                        rep_err(out, &crate::eval::AgrError::Other("Expected logfmt, found None".to_string()));
                        return OpOut::Drop;
                    }
                },
            };
            let mut m = std::collections::BTreeMap::new();
            for part in src.split_whitespace() {
                if let Some(i) = part.find('=') {
                    let k = part[..i].to_string();
                    let v = part[i + 1..].to_string();
                    m.insert(k, Value::Str(v));
                }
            }
            OpOut::Keep(Record::Fields(m))
        }
        Op::Split { field, sep, name } => {
            let sep = sep.clone().unwrap_or_else(|| ",".to_string());
            let src = match field {
                Some(f) => match rec.get(f) {
                    Some(Value::Str(s)) => s,
                    Some(other) => other.display(),
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!("No value for key \"{}\"", f)),
                        );
                        return OpOut::Drop;
                    }
                },
                None => match rec.raw() {
                    Some(s) => s.clone(),
                    None => {
                        rep_err(out, &crate::eval::AgrError::Other("Expected a string, found None".to_string()));
                        return OpOut::Drop;
                    }
                },
            };
            let parts: Vec<Value> = if sep.is_empty() {
                vec![Value::Str(src.clone())]
            } else {
                src.split(sep.as_str()).map(|p| Value::Str(p.to_string())).collect()
            };
            let arr = Value::Arr(parts);
            let mut newrec = rec.clone();
            match (field, name) {
                (Some(f), Some(n)) => {
                    newrec.set(f.clone(), Value::Str(src.clone()));
                    newrec.set(n, arr);
                }
                (Some(f), None) => {
                    newrec.set(f.clone(), arr);
                }
                (None, Some(n)) => {
                    newrec.set(n, arr);
                }
                (None, None) => {
                    newrec.set("_split".to_string(), arr);
                }
            }
            OpOut::Keep(newrec)
        }
        Op::Parse {
            mode,
            pattern,
            from,
            names,
            nodrop,
            noconvert,
        } => {
            let src = match from {
                Some(f) => match rec.get(f) {
                    Some(Value::Str(s)) => s,
                    Some(other) => other.display(),
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(format!("No value for key \"{}\"", f)),
                        );
                        return OpOut::Drop;
                    }
                },
                None => match rec.raw() {
                    Some(s) => s.clone(),
                    None => {
                        rep_err(out, &crate::eval::AgrError::Other("Expected a string, found None".to_string()));
                        return OpOut::Drop;
                    }
                },
            };
            match mode {
                ParseMode::Plain => {
                    let wildcards = pattern.matches('*').count();
                    if wildcards != names.len() {
                        out.errors.push(format!(
                            "Wrong number of patterns for parse. Pattern has {} but {} were extracted",
                            wildcards,
                            names.len()
                        ));
                        return OpOut::Drop;
                    }
                    let mut vals = Vec::new();
                    if !plain_parse(&src, pattern, &mut vals) {
                        if *nodrop {
                            let mut newrec = rec.clone();
                            for n in names.iter() {
                                newrec.set(n.clone(), Value::Null);
                            }
                            return OpOut::Keep(newrec);
                        }
                        return OpOut::Drop;
                    }
                    let mut newrec = rec.clone();
                    for (n, v) in names.iter().zip(vals.iter()) {
                        let val = if *noconvert {
                            Value::Str(v.clone())
                        } else if let Ok(f) = v.parse::<f64>() {
                            Value::Num(f)
                        } else {
                            Value::Str(v.clone())
                        };
                        newrec.set(n.clone(), val);
                    }
                    OpOut::Keep(newrec)
                }
                ParseMode::Regex => {
                    let re = crate::regex_cache::get(pattern);
                    match re.captures(&src) {
                        Some(caps) => {
                            let mut newrec = rec.clone();
                            for n in names.iter() {
                                let v = caps.name(n).map(|m| m.as_str().to_string());
                                match v {
                                    Some(s) => {
                                        let val = if *noconvert {
                                            Value::Str(s)
                                        } else if let Ok(f) = s.parse::<f64>() {
                                            Value::Num(f)
                                        } else {
                                            Value::Str(s)
                                        };
                                        newrec.set(n.clone(), val);
                                    }
                                    None => {
                                        if !*nodrop {
                                            return OpOut::Drop;
                                        }
                                        newrec.set(n.clone(), Value::Null);
                                    }
                                }
                            }
                            OpOut::Keep(newrec)
                        }
                        None => {
                            if *nodrop {
                                let mut newrec = rec.clone();
                                for n in names.iter() {
                                    newrec.set(n.clone(), Value::Null);
                                }
                                return OpOut::Keep(newrec);
                            }
                            OpOut::Drop
                        }
                    }
                }
            }
        }
        Op::Fields { mode, names } => {
            if names.is_empty() {
                return OpOut::Keep(rec);
            }
            let m = rec.fields().clone();
            let mut newm = std::collections::BTreeMap::new();
            match mode {
                FieldsMode::Only => {
                    for n in names.iter() {
                        if let Some(v) = m.get(n) {
                            newm.insert(n.clone(), v.clone());
                        }
                    }
                }
                FieldsMode::Except => {
                    for (k, v) in m.iter() {
                        if !names.contains(k) {
                            newm.insert(k.clone(), v.clone());
                        }
                    }
                }
            }
            OpOut::Keep(Record::Fields(newm))
        }
        Op::Where(e) => match crate::eval::eval(e, &rec) {
            Ok(v) => {
                if crate::eval::truthy(&v) {
                    OpOut::Keep(rec)
                } else {
                    OpOut::Drop
                }
            }
            Err(err) => {
                rep_err(out, &err);
                OpOut::Drop
            }
        },
        Op::Limit(n) => OpOut::Keep(rec), // handled by the caller
        Op::FieldExpr(e, name) => match crate::eval::eval(e, &rec) {
            Ok(v) => {
                let mut nr = rec.clone();
                nr.set(name.clone(), v);
                OpOut::Keep(nr)
            }
            Err(err) => {
                rep_err(out, &err);
                OpOut::Drop
            }
        },
        Op::IfOp(args, name) => {
            let c = match crate::eval::eval(&args[0], &rec) {
                Ok(v) => crate::eval::truthy(&v),
                Err(err) => {
                    rep_err(out, &err);
                    return OpOut::Drop;
                }
            };
            let v = if c { args[1].clone() } else { args[2].clone() };
            match crate::eval::eval(&v, &rec) {
                Ok(val) => {
                    let mut nr = rec.clone();
                    nr.set(name.clone(), val);
                    OpOut::Keep(nr)
                }
                Err(err) => {
                    rep_err(out, &err);
                    OpOut::Drop
                }
            }
        }
        Op::Timeslice {
            expr,
            seconds,
            nanos: _,
            name,
        } => {
            let v = match crate::eval::eval(expr, &rec) {
                Ok(v) => v,
                Err(err) => {
                    rep_err(out, &err);
                    return OpOut::Drop;
                }
            };
            let secs = match &v {
                Value::Str(s) => match crate::dates::parse_date(s) {
                    Some(t) => t,
                    None => {
                        rep_err(
                            out,
                            &crate::eval::AgrError::Other(
                                "The 'parseDate' function failed with the error: NoDate".to_string(),
                            ),
                        );
                        return OpOut::Drop;
                    }
                },
                Value::Num(n) => *n as i64,
                _ => {
                    rep_err(out, &crate::eval::AgrError::Other("Expected a date".to_string()));
                    return OpOut::Drop;
                }
            };
            let w = seconds.max(1.0) as i64;
            let t = secs - (secs.rem_euclid(w));
            let (y, mo, d, h, mi, s) = crate::dates::epoch_to_civil(t);
            let mut nr = rec.clone();
            nr.set(
                name.clone(),
                Value::Str(format!(
                    "{:04}-{:02}-{:02} {:02}:{:02}:{:02} UTC",
                    y, mo, d, h, mi, s
                )),
            );
            OpOut::Keep(nr)
        }
        Op::Total(e, name) => {
            let v = match crate::eval::eval(e, &rec) {
                Ok(v) => v,
                Err(err) => {
                    rep_err(out, &err);
                    return OpOut::Drop;
                }
            };
            let n = match v {
                Value::Num(n) => n,
                _ => 0.0,
            };
            let mut nr = rec.clone();
            nr.set(name.clone(), Value::Num(n));
            OpOut::Keep(nr)
        }
        Op::Alias(name) => {
            if let Some(ops) = alias_expand(name) {
                let mut r = rec;
                for o in ops.iter() {
                    match apply_op(o, r, out, _mode, _fmt, _pending) {
                        OpOut::Keep(nr) => r = nr,
                        OpOut::Drop => return OpOut::Drop,
                    }
            }
                OpOut::Keep(r)
            } else {
                OpOut::Keep(rec)
            }
        }
        Op::Sort(_, _) => OpOut::Keep(rec),
        Op::Count { .. } | Op::Sum(..) | Op::Min(..) | Op::Max(..) | Op::Average(..)
        | Op::CountDistinct(..) | Op::Percentile(..) => OpOut::Keep(rec),
    }
}

/// greedy `*` based parse: `*` matches as much as possible while allowing the
/// rest of the pattern to match
fn plain_parse(src: &str, pattern: &str, out: &mut Vec<String>) -> bool {
    let parts: Vec<&str> = pattern.split('*').collect();
    // pattern has N+1 literal parts, N of which are followed by a wildcard
    let n = parts.len() - 1;
    // recursive match
    fn go(rest: &str, parts: &[&str], out: &mut Vec<String>) -> bool {
        if parts.is_empty() {
            return rest.is_empty();
        }
        if parts.len() == 1 {
            // last literal must match the end
            if rest.len() >= parts[0].len() && rest.ends_with(parts[0]) {
                out.push(rest[..rest.len() - parts[0].len()].to_string());
                return true;
            }
            return false;
        }
        // parts[0] must be a prefix, then a wildcard capturing greedily
        let head = parts[0];
        if !rest.starts_with(head) {
            return false;
        }
        let after = &rest[head.len()..];
        // wildcard is greedy: try the longest capture that allows the rest to match
        for i in (0..=after.len()).rev() {
            let cap = &after[..i];
            let tail = &after[i..];
            let save = out.len();
            out.push(cap.to_string());
            if go(tail, &parts[1..], out) {
                return true;
            }
            out.truncate(save);
        }
        false
    }
    // whitespace in the pattern matches any whitespace
    let p: String = pattern
        .chars()
        .map(|c| if c.is_whitespace() { '\u{1}' } else { c })
        .collect();
    let s: String = src
        .chars()
        .map(|c| if c.is_whitespace() { '\u{1}' } else { c })
        .collect();
    let pparts: Vec<&str> = p.split('*').collect();
    go(&s, &pparts, out)
}
